quests[65417] = { id = 65417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbindungen finden" }
quests[65419] = { id = 65419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protoformsynthese", description = "<Pocopoc springt unruhig herum. Nachdem Ihr Euch mit den Grundlagen des Dacaparischen vertraut gemacht habt, ist er nun sehr aufgeregt und drängt Euch, ihm an einen anderen Ort im Reich zu folgen.>", sourceObjective = "Eskortiert Pocopoc zu der Protoformsyntheseschmiede.", completion = "<Pocopoc deutet auf einige Steuerungselemente auf diesem Gerät und Ihr versteht gerade genug Dacaparisch, um zu begreifen, warum er Euch hierhergebracht hat. Mit einigen Materialien, die innerhalb von Zereth Mortis gefunden werden können, und Pocopocs Hilfe könnt Ihr diese Maschine starten und vollentwickelte Wesen erschaffen, die auf spezifischen Bauplänen basieren.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65420] = { id = 65420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ermessensfragen", description = "Oh nein... Nein nein nein... Was hab ich getan?\n\nDie Ältesten werden niemals erlauben, dass ich zurückkehre. Sie werden mich verbannen, so wie sie es mit Firim taten.\n\nBitte, Fremdling, sprecht mit dem Ältesten Amir in der Huld des Pilgers. Richtet ihm meinen Dank dafür aus, dass er Euch geschickt hat, und erzählt ihm, was hier passiert ist. Er wird verstehen, warum ich nicht zurückkehren kann.", sourceObjective = "Sprecht mit dem Ältesten Amir in der Huld des Pilgers.", completion = "Tahli ist am Leben? Und Ihr habt ein Archiv der Automas mit ihrer Hilfe konserviert? Oh, du meine Güte. Das... muss ich erst mal verarbeiten.\n\nUnd ihre Schuldgefühle haben sie natürlich davon abgehalten, nach Hause zurückzukehren. Oh, Tahli.", sourceObjectiveStatus = "unverified-source-field" }
quests[65421] = { id = 65421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf jeden Berg", description = "Hoffentlich lernt Ihr schnell, {class}. Ich hab nämlich keine Zeit für eine Lehrstunde!\n\nSchnappt Euch einen Rucksack und findet einen Weg zur Spitze.\n\nWenn Ihr oben seid, werft unserer Yips diesen Fallschirm zu. Die arme Kleine hat sich in ein paar Ranken verfangen, als die Luftelementare unser Flugzeug zum Absturz gebracht haben!\n\nBeeilt Euch, damit wir schleunigst hier rauskommen!", sourceObjective = "Schnappt Euch die Kletterausrüstung, sucht Euch einen Haltegriff und klettert die Klippe hoch, um Pfadfinderin Yips zu befreien!", progress = "Beeilt Euch! Yips kann nicht lange durchhalten!", completion = "Gut geklettert! Yips schuldet Euch ein paar Getränke!\n\nAch, die Elementare? Nee, keine Sorge. Das ist UNSER Abenteuer!\n\n<Rocky durchsiebt die Luftelementare vergnügt weiter mit Geschossen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65422] = { id = 65422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd nach Schätzen ist nicht leicht", description = "Ich kann es in Euren Augen sehen: Ihr wollt unbedingt den Gipfel dieses Berges erklimmen und herausfinden, was dort oben ist!\n\nWir Kletterer erkennen uns immer gegenseitig. Wir lassen uns von keinem Berg klein machen, nicht wahr?\n\nNur gut, dass ich eine Menge Kletterausrüstung dabei habe. Schnappt Euch einen Rucksack und findet einen Weg nach oben!", sourceObjective = "Schnappt Euch die Kletterausrüstung, sucht Euch dann einen Haltegriff und klettert auf den Gipfel des Berges, ohne den Halt zu verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[65424] = { id = 65424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sayaaden-Scharaden", description = "Als <mein Meister/meine Meisterin> solltet Ihr dies wissen: Ich bin recht flexibel dabei, Euren... Präferenzen entgegenzukommen.\n\n<Der Dämon deutet auf sich selbst.>\n\nWenn Euch das hier nicht gefällt, dann kann ich auch bei einer einzigen meiner Gestalten bleiben, die Euch bis in Eure Träume verfolgen wird. Einer Eurer Mentoren sollte Euch lehren können, wie Ihr Euer Beschwörungsritual anpasst.\n\nIhr könnt es aber natürlich auch einfach mir überlassen... Ich bin mir sicher, das wird für uns alle eine interessante Erfahrung.", sourceObjective = "Sprecht mit Kazak Dunkelschrei in Orgrimmar über die Anpassung Eures Zaubers 'Sukkubus beschwören'.", completion = "Ein interessanter Vorschlag... den ich selber mal ausprobieren sollte.\n\nSprecht mich an, wenn Ihr Euer Beschwörungsritual anpassen möchtet. Ich glaube, ich weiß, worauf sie angespielt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[65425] = { id = 65425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sayaaden-Scharaden", description = "Als <mein Meister/meine Meisterin> solltet Ihr dies wissen: Ich bin recht flexibel dabei, Euren... Präferenzen entgegenzukommen.\n\n<Der Dämon deutet auf sich selbst.>\n\nWenn Euch das hier nicht gefällt, dann kann ich auch bei einer einzigen meiner Gestalten bleiben, die Euch bis in Eure Träume verfolgen wird. Einer Eurer Mentoren sollte Euch lehren können, wie Ihr Euer Beschwörungsritual anpasst.\n\nIhr könnt es aber natürlich auch einfach mir überlassen... Ich bin mir sicher, das wird für uns alle eine interessante Erfahrung.", sourceObjective = "Sprecht mit Evelyn Dorn in Sturmwind über die Anpassung Eures Zaubers 'Sukkubus beschwören'.", completion = "Was für ein faszinierendes Konzept. Ich habe nicht gewusst, dass ein Sukkubus zu so etwas fähig ist.\n\nSprecht mich an, wenn Ihr Euer Beschwörungsritual anpassen möchtet. Ich glaube, ich weiß, worauf sie angespielt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[65426] = { id = 65426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Komponente", description = "<Schlundgänger/Schlundgängerin>! Schaut.\n\nWir beschäftigen uns schon seit längerer Zeit mit dieser Automakomponente. Ihre Chiffren ähneln denen der Komponenten in der Nähe und innerhalb des Protoformrepositoriums.\n\nKodahs letzte Bemühungen sollen nicht umsonst gewesen sein. Bitte bringt diese Komponente zum Repositorium, das unser Freund wiederhergestellt hat.", sourceObjective = "Hebt den Protoformkatalysator auf und bringt ihn zum Protoformrepositorium.", progress = "Der Sterbliche strebt nach Protoformsynthese.", completion = "Grüße, Architekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65427] = { id = 65427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Architektenneuling", description = "Die Architekten haben Prototypenentwürfe erstellt, um die Ziele der Ersten zu erfüllen.\n\nDieses Archiv enthielt viele dieser Entwürfe.\n\nEinige gingen während der Schlundinvasion verloren oder wurden verderbt.\n\nEin unberührtes Entwurfsgitter und Werkzeuge wurden in der Nähe geortet. <Der Sterbliche/Die Sterbliche> wird sie beschaffen, um den Syntheseprozess zu beginnen.", sourceObjective = "Sammelt 1 Cervidengitter und 3 Protoformwerkzeuge und bringt sie zur Dienersteuerung im Protoformrepositorium.", progress = "Konnten die notwendigen Materialien beschafft werden?", completion = "Erfolg.\n\nDas Protoformrepositorium ist jetzt wiederhergestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65431] = { id = 65431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Nachforschungen: Akkolarisch", description = "Ihr habt bereits einige wundersame Entdeckungen gemacht, <Schlundänger/Schlundgängerin>, doch es warten noch weitere Geheimnisse auf Euch.\n\nDen ersten Schritt habt Ihr getan und die Konsole freigeschaltet. Ich glaube, Ihr seid bereit für den nächsten.\n\nUntersucht die Konsole und findet heraus, welcher Teil des Musters sich Euch offenbart.", sourceObjective = "Untersucht die Chiffrenkonsole in der Höhle des Verbannten weiter.", completion = "Neues Wissen! Die Ersten haben wahrlich erstaunliche Erkenntnisse hinterlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65432] = { id = 65432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Nachforschungen: Dacaparisch", description = "<Die Konsole summt vor mysteriöser Energie.>", sourceObjective = "Untersucht die Chiffrenkonsole in der Höhle des Verbannten weiter.", completion = "<Eine seltsame Energie umgibt die Konsole.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65433] = { id = 65433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Nachforschungen: Violonisch", description = "<Die Konsole summt vor mysteriöser Energie.>", sourceObjective = "Untersucht die Chiffrenkonsole in der Höhle des Verbannten weiter.", progress = "<Unter Umständen sind weitere Untersuchungen notwendig.>", completion = "<Eine seltsame Energie umgibt die Konsole.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65435] = { id = 65435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dracheninseln warten", description = "Helden der Horde, ich bringe Neuigkeiten. Die Dracheninseln erwachen!\n\nNach der Zerschlagung fielen die Inseln in einen tiefen Schlummer. Doch nun endlich haben sie meinesgleichen und mich nach Hause berufen.\n\nDie Inseln bergen viele Wunder, doch auch nicht minder Gefahren. Um unser rechtmäßiges Erbe zurückzuerobern, sind wir auf die Hilfe unserer sterblichen Verbündeten angewiesen.\n\nIch werde dem Rat der Horde in Orgrimmar gleich die Einladung der Aspekte präsentieren. Trefft mich dort und wir werden sehen, was der Rat dazu sagt.", sourceObjective = "Trefft Euch mit Ebyssian in Orgrimmar.", completion = "Ich bin dankbar, dass Ihr dem Ruf gefolgt seid. Euer Mut wird uns auf dem Weg, der vor uns liegt, noch dienlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[65436] = { id = 65436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dracheninseln warten", description = "Wundervolle Neuigkeiten, meine lieben Freunde! Die Dracheninseln erwachen!\n\nNach der Zerschlagung ließ mein Volk die Dracheninseln in einem tiefen Schlummer zurück. Doch nun endlich spüren wir den Ruf nach Hause.\n\nDie Inseln bergen viele Wunder, doch sie sind nicht ohne Gefahren. Um unser rechtmäßiges Erbe zurückzuerobern, sind wir auf die Hilfe unserer sterblichen Verbündeten angewiesen.\n\nTrefft mich in Sturmwind. Ich muss der Allianz die Einladung der Aspekte vorlegen.", sourceObjective = "Trefft Euch mit Furorion in Sturmwind.", completion = "Die Einladung der Aspekte gilt auch für Euch, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[65437] = { id = 65437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einladung der Aspekte", sourceObjective = "Sprecht mit Ebyssian.", completion = "Ich fühle mich geehrt, dass Ihr ins Heimatland der Drachenheit reist.\n\nEiner Eurer Verbündeten hilft Euch gern bei den Vorbereitungen für das, was vor Euch liegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65438] = { id = 65438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasser Questbeginn", description = "Der Beginn des Azurblauen Gebirges." }
quests[65439] = { id = 65439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern in den Winden", sourceObjective = "Sprecht mit Erzmagier Khadgar außerhalb von Orgrimmar.", progress = "Unsere Reise beginnt mit Euch.", completion = "Das sind in der Tat beunruhigende Neuigkeiten, aber gewiss wart Ihr Euch der Gefahren bewusst, die uns erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65443] = { id = 65443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionskoordination", description = "Erfreut, Euch kennenzulernen, ich bin Naleidea Flussglanz!\n\nDie Einladung, die Dracheninseln aufzusuchen, ist eine überaus aufregende Aussicht! Meint Ihr nicht auch?\n\nDie Archäologische Akademie hat ihre Ressourcen mit den entsprechenden Mitgliedern unserer Expedition zusammengelegt, um uns bei der Koordination unserer Anstrengungen zu unterstützen. Als Mitglied der Drachenschuppenexpedition ist es mir eine Ehre, Euch willkommen zu heißen!\n\nZunächst müssen wir jedoch weitere Mitglieder für unsere Reise finden. Wollen wir beginnen?", sourceObjective = "Rekrutiert Forscher, Handwerker und Gelehrte in ganz Orgrimmar für die Expedition zu den Dracheninseln.", progress = "Habt Ihr bereits mit den anderen gesprochen?", completion = "Ich bin überzeugt, dass diese Expedition ein großer Erfolg wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[65444] = { id = 65444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Dracheninseln!", description = "Unsere Expeditionsvorhut ist auf den Dracheninseln gelandet.\n\nDank den Bemühungen der mutigen Mitglieder der Drachenschuppenexpedition haben wir einen geschützten Landeplatz auf den Dracheninseln eingerichtet und Kontakt mit der Botschaft des Drachenschwarms aufgenommen.\n\nWollt Ihr uns auf unserer nächsten Reise zu den Dracheninseln begleiten?", sourceObjective = "Nehmt die Draufgängerische Drachenschuppe vom Zeppelinturm außerhalb von Orgrimmar zu den Dracheninseln.", completion = "Willkommen auf den Dracheninseln!", sourceObjectiveStatus = "unverified-source-field" }
quests[65445] = { id = 65445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notwendige Ressourcenbeschaffung", description = "Verschlinger fressen Neopartikel.\n\nWir benötigen Neopartikel für notwendige Schöpfungsarbeiten. Ohne sie ist es uns unmöglich, unsere Arbeit abzuschließen.\n\nVernichtet die Verschlinger und bergt die Neopartikel.", sourceObjective = "Beschafft 30 Neopartikelrückstände und 3 ausgehärtete Neopartikel von Verschlingern in Zereth Mortis.", progress = "Habt Ihr die Neopartikel gesammelt?", completion = "Ihr habt die Aufgabe abgeschlossen. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[65448] = { id = 65448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilger erneut willkommen", description = "<Nun, da der Tempel in seinen alten Zustand zurückversetzt wurde und die Verteidigung wieder aktiv ist, sollte die Quelle vor Verschlingern sicher sein. Konservator Olem wird wissen wollen, was Ihr hier erreicht habt.>", sourceObjective = "Sprecht mit Konservator Olem und überbringt die guten Nachrichten.", progress = "Ihr seid zurück. Und wie erwartet, hattet Ihr Erfolg.", completion = "Wie ich es erwartet hatte. Eure Ankunft war im Entwurf der Ersten enthalten! Ich freue mich auf das Vermächtnis, das Ihr im Land unserer Schöpfer schmieden werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[65451] = { id = 65451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übungsmaterialien", description = "So etwas wie diese Protodrachen habe ich noch nie auf Azeroth gesehen.\n\nIhre Schuppen scheinen von Natur aus feuerfest zu sein, stärker als Stahl, und sie büßen dabei nicht an Flexibilität ein. Unglaublich.\n\nMeine Kunsthandwerker... und zwar alle... wollen unbedingt ein paar dieser Schuppen in die Hände bekommen, um damit zu arbeiten.\n\nBeginnt mit den Welpen. Ihre kleineren Schuppen sollten biegsamer sein und uns dabei helfen, unsere Techniken zu verbessern.", sourceObjective = "Sammelt 20 Urprotowelpenschuppen.", progress = "Habt ihr die Schuppen schon? Die Alchemisten werden langsam unruhig, und das macht mich immer so nervös.", completion = "<Boss Magor untersucht die Schuppen sorgfältig.>\n\nUnsere Handwerker werden sie gut brauchen können. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[65452] = { id = 65452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forscher in Not", sourceObjective = "Rettet 3 Mitglieder der Drachenschuppenexpedition an der Wilden Küste.", progress = "Sind die Expeditionsmitglieder in Sicherheit?", completion = "Die Drachen sind nicht hier, um uns zu treffen, wie Ebyssian versprochen hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[65453] = { id = 65453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgeziefer", description = "<Glutdresch wirft einen misstrauischen Blick auf die Protodrachen, die hinter ihr auf dem Gebirgskamm lauern.>\n\nIch könnte schwören, dass diese Protodrachen jedes Mal, wenn ich ihnen den Rücken zuwende, näher an das Lager herankommen...\n\nDas sind nicht die Drachen, die Ebyssian uns hier vorstellen wollte.\n\nDie Protodrachen sind skrupellose Raubtiere, mit denen man nicht verhandeln kann. Wir müssen ebenso skrupellos sein.\n\nDezimiert ihre Zahl, um ihre Kühnheit zu mäßigen, sonst ist diese Expedition zu Ende, bevor sie richtig begonnen hat.", sourceObjective = "Tötet 8 Urprotodrachen an der Wilden Küste.", completion = "Das sollte sie eine Weile lang davon abhalten, die Expeditionslager anzugreifen.\n\nAuf den Dracheninseln gilt \"Fressen oder gefressen werden\", {name}. Das solltet Ihr Euch merken.", sourceObjectiveStatus = "unverified-source-field" }
quests[65456] = { id = 65456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firim, der Verlorengeglaubte", description = "Ich habe hier Daten gesammelt, als sich Euer Portal öffnete. Dadurch wurden diese Mechanismen aktiviert, welche die Tore versperren.\n\nDa ist es ja nur recht und billig, wenn Ihr die Torschlüssel einsammelt, oder? Wir reden während Eurer Suche weiter.", sourceObjective = "Helft Firim das Tor nach Zereth Mortis zu öffnen.", progress = "Und nun vorwärts.", completion = "Ihr seid stärker und geduldiger, als Ihr ausseht.", sourceObjectiveStatus = "unverified-source-field" }
quests[65460] = { id = 65460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erstes kantarisches Protoschloss", description = "<Schlundgänger/Schlundgängerin>, wie es scheint, hat Pocopoc Enigmundisch gelernt. Damit erhaltet Ihr Zugriff auf die Schätze der Schöpfung. Ihr findet mehrere Arten dieser Schätze überall in Zereth Mortis.\n\nUm mir bei meinen Forschungen zu helfen, müsst Ihr verschiedene Chiffren entziffern können, wie beispielsweise beim kantarischen Protoschloss.\n\nLasst mich Euch nun zeigen, wie Ihr mir zur Hand gehen könnt.", sourceObjective = "Schließt die Aufgabe um das kantarische Protoschloss ab.", completion = "Gute Arbeit, Schlundgänger.\n\nMit genügend Energie und ausreichendem Bemühen wird Euer Begleiter Euch gewiss dabei helfen können, diese Herausforderungen zu überwinden, sollten sie Euch zu viel werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[65461] = { id = 65461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erstes mezzonisches Protoschloss", description = "Um mir bei meinen Forschungen zu helfen, müsst Ihr verschiedene Progenitorchiffren wie beim mezzonischen Protoschloss dekodieren. Lasst mich Euch zeigen, was Ihr tun müsst.", sourceObjective = "Schließt die Aufgabe um das mezzonische Protoschloss ab.", progress = "Nutzt dieses Wissen, um da draußen mehr Daten zu sammeln.", completion = "Nutzt dieses Wissen und sammelt da draußen mehr Daten, Schlundgänger.\n\nÜber einen weiteren Schatz der Schöpfung muss ich Euch noch belehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65463] = { id = 65463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle der Ersten", description = "<Ein Sterblicher/Eine Sterbliche>? Hier? Wie ungewöhnlich! Willkommen in der Huld des Pilgers. Ich wünschte, die Umstände Eures Besuchs wären besser. Die Pilger besuchen hier normalerweise die heilige Quelle der Ersten.\n\nUnglücklicherweise ist die Quelle versiegt. Ich verstehe das einfach nicht. Die Schöpfungen der Ersten sollten unfehlbar sein!\n\nDiese Situation ist so ungewöhnlich wie Eure Ankunft. Vielleicht könnt Ihr mir helfen? Reist zur Quelle und sprecht mit Konservator Olem.", sourceObjective = "Sprecht mit Konservator Olem über das Problem mit der Quelle.", completion = "Ein Sterblicher? Hier? Die Entwürfe der Ersten sind unbegreiflich.", sourceObjectiveStatus = "unverified-source-field" }
quests[65466] = { id = 65466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erstes fugalisches Protoschloss", description = "Um mir bei meinen Forschungen zu helfen, müsst Ihr verschiedene Progenitorchiffren wie beim fugalischen Protoschloss dekodieren. Das ist eine schwierige Chiffre. Lasst mich Euch zeigen, was Ihr tun müsst.", sourceObjective = "Schließt die Aufgabe um das fugalische Protoschloss ab.", completion = "Sehr gut, Schlundgänger. Das war wirklich beeindruckend.\n\nVergesst nicht, dass Euer Begleiter Euch bei den Protoschlössern helfen kann, sofern er über ausreichend Energie verfügt.\n\nNehmt nun Euer neu gewonnenes Wissen und setzt es dort draußen um.", sourceObjectiveStatus = "unverified-source-field" }
quests[65467] = { id = 65467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truthahnseele", description = "<Die Truthahnseele ist kühn und unerschütterlich. Ihr könnt jetzt die Gestalt des Truthahns nutzen.>", sourceObjective = "Bringt die Truthahnseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, ein Truthahn! Jetzt könnt Ihr auch gackern wie einer!", sourceObjectiveStatus = "unverified-source-field" }
quests[65475] = { id = 65475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreischende Botschaft", description = "<Ihr zieht einen Fetzen Pergament aus dem mit Blut getränkten, besudelten Ranzen von Rocfresser. Alles, was Ihr erkennt, ist das Bild einer Harpyie, die große Eier verschlingt.\n\nIhr seid Euch sicher, dass die dicken, unverständlichen Kratzspuren Eurer Lieblingsornithologin, Harleen Hohnzirper, einiges verraten werden.>", sourceObjective = "Bringt die Schriftrolle des Kreischerschwarms zu Harleen Hohnzirper an den Blaufederklippen.", progress = "Schon zurück von den Höhlen?", completion = "Oha! Das ist sicherlich keine Speisekarte, was Ihr da bei Euch tragt.\n\nOder vielleicht doch...", sourceObjectiveStatus = "unverified-source-field" }
quests[65486] = { id = 65486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Bild", description = "Entschuldigt, ich verlier mich manchmal sehr im Teleskop.\n\nFindet Ihr nicht auch, dass die Welt sich aus der Ferne viel leichter versteh'n lässt? Keine Störungen von außen, nur die Natur, die ihren Weg ohne uns geht...\n\n<Akunda die Katalogisiererin seufzt.>\n\nWie ich sehe, hat Coralie Euch eine Kamera gegeben. Gut.\n\nFahrt mit Fren den Fluss entlang und macht ein paar Fotografien von den Wildtieren in ihrem natürlichen Lebensraum, damit ich sie studier'n kann.", sourceObjective = "Nehmt das Katalogisiererfloß mit Fren und macht Bilder von der heimischen Tierwelt.", progress = "Fren wird das Floß für Euch rudern. Keine Sorge, sie is' die Allerbeste!", completion = "<Akunda geht die Fotografien durch und analysiert sie aufmerksam.>\n\nBe-mer-kens-wert. Und überraschend. So viele neue Erkenntnisse, und so viele neue Art'n zu verzeichnen!\n\nHabt Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[65490] = { id = 65490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Exkremente", description = "Die Harpyien sind ja eine erfreuliche Überraschung und so, aber ich bin nur aus einem einzigen Grund in diese Berge gekommen: EXKREMENTE!\n\nGenauer gesagt, wegen der Exkremente von Blaufederrocs, die von Käfern gefressen und verdaut wurden. Die Magensäfte der Skarabäen erhöhen den explosiven Stickstoffgehalt um das Zehnfache! Mindestens!\n\nHier nehmt Hohnzirpers Autoexkrementsammler. Tretet auf die Skarabäen auf dem Höhlenboden ein und benutzt den Sammler, um die Belohnungen zu ernten.\n\nBringt ihn vollständig gefüllt zurück, damit wir mit dem richtigen Spaß anfangen können: EXPLOSIONEN!", sourceObjective = "Füllt Professorin Hohnzirpers Autoexkrementsammler.", completion = "Oh, ja! Das ist gut!\n\nHabt Ihr je darüber nachgedacht, diese Arbeit zu Eurem Beruf zu machen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[65504] = { id = 65504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenfalkenseele", description = "<Die Drachenfalkenseele ist wendig und widerstandsfähig. Ihr könnt jetzt die Gestalt des Drachenfalken nutzen.>", sourceObjective = "Bringt die Drachenfalkenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Drachenfalke. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65505] = { id = 65505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skorpidenseele", description = "<Die Skorpidenseele ist wild und gierig. Ihr könnt jetzt die Gestalt des Skorpiden nutzen.>", sourceObjective = "Bringt die Skorpidenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Skorpid. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65506] = { id = 65506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rochenseele", description = "<Die Rochenseele ist schlau und schnell. Ihr könnt jetzt die Gestalt des Rochens nutzen.>", sourceObjective = "Bringt die Rochenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Rochen. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65507] = { id = 65507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekkseele", description = "<Die Elekkseele ist schlau und mächtig. Ihr könnt jetzt die Gestalt des Elekks nutzen.>", sourceObjective = "Bringt die Elekkseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Elekk. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65508] = { id = 65508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitschreiterseele", description = "<Die Weitschreiterseele ist flink und neugierig. Ihr könnt jetzt die Gestalt des Weitschreiters nutzen.>", sourceObjective = "Bringt die Weitschreiterseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Weitschreiter. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65509] = { id = 65509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fledermausseele", description = "<Die Fledermausseele ist listig und schnell. Ihr könnt jetzt die Gestalt der Fledermaus nutzen.>", sourceObjective = "Bringt die Fledermausseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, die Fledermaus. Ihr könnt ihre Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65510] = { id = 65510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutosaurusseele", description = "<Die Brutosaurusseele ist treu und tapfer. Ihr könnt jetzt die Gestalt des Brutosaurus nutzen.>", sourceObjective = "Bringt die Brutosaurusseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Brutosaurus. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65512] = { id = 65512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silithidenseele", description = "<Die Silithidenseele ist brutal und schnell. Ihr könnt jetzt die Gestalt des Silithiden nutzen.>", sourceObjective = "Bringt die Silithidenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Silithid. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65513] = { id = 65513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gromitseele", description = "<Die Gromitseele ist quirlig und neugierig. Ihr könnt jetzt die Gestalt des Gromits nutzen.>", sourceObjective = "Bringt die Gromitseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Oh, ein Gromit! Die hüpfen so fröhlich umher!", sourceObjectiveStatus = "unverified-source-field" }
quests[65514] = { id = 65514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gürteltierseele", description = "<Die Gürteltierseele ist vorsichtig und widerstandsfähig. Ihr könnt jetzt die Gestalt des Gürteltiers nutzen.>", sourceObjective = "Bringt die Gürteltierseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Oh, ein Gürteltier! Die sind so gut geschützt!", sourceObjectiveStatus = "unverified-source-field" }
quests[65515] = { id = 65515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schweineseele", description = "<Die Schweineseele ist neugierig und beharrlich. Ihr könnt jetzt die Gestalt des Schweins nutzen.>", sourceObjective = "Bringt die Schweineseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Oh, ein Schwein! Jetzt könnt Ihr auch zufrieden grunzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65516] = { id = 65516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schafseele", description = "<Die Schafseele ist ruhig und beständig. Ihr könnt jetzt die Gestalt des Schafs nutzen.>", sourceObjective = "Bringt die Schafseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Oh, ein Schaf! Die sind so putzig und knuddelig!", sourceObjectiveStatus = "unverified-source-field" }
quests[65517] = { id = 65517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinguinseele", description = "<Die Pinguinseele ist verspielt und gesellig. Ihr könnt jetzt die Gestalt des Pinguins nutzen.>", sourceObjective = "Bringt die Pinguinseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Oh, ein Pinguin! Jetzt könnt Ihr auch herumrutschen wie einer!", sourceObjectiveStatus = "unverified-source-field" }
quests[65518] = { id = 65518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bienenseele", description = "<Die Bienenseele ist fürsorglich und agil. Ihr könnt jetzt die Gestalt der Biene nutzen.>", sourceObjective = "Bringt die Bienenseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Oh, eine Biene! Jetzt könnt Ihr auch summen wie eine!", sourceObjectiveStatus = "unverified-source-field" }
quests[65519] = { id = 65519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneckenseele", description = "<Die Schneckenseele ist vorsichtig und geduldig. Ihr könnt jetzt die Gestalt der Schnecke nutzen.>", sourceObjective = "Bringt die Schneckenseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Oh, eine Schnecke! Jetzt könnt Ihr auch kriechen wie eine!", sourceObjectiveStatus = "unverified-source-field" }
quests[65563] = { id = 65563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Kasea", description = "Ich hoffe, es macht Euch nichts aus, aber ich habe ein paar Eurer Materialien benutzt, um etwas zu basteln, um das Kasea mich gebeten hat.\n\nKönntet Ihr es ihr bitte bringen?", sourceObjective = "Bringt den Klingenhelm zu Kasea Zornesschmied.", completion = "Thurgaden hat es also endlich hinbekommen? Und er hat auch noch genau die richtige Person mitgeschickt!", sourceObjectiveStatus = "unverified-source-field" }
quests[65564] = { id = 65564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guter feuriger Junge", description = "Ich bilde alle Hundearten aus, solange sie feurig sind. Ich habe Grimmheul hier schon als kleinen Welpen ausgebildet, aber für das Leben in der Schattenschmiede ist er nicht gemacht!\n\nGrimmheul braucht eine besondere Bezugsperson, die ihm ganz Azeroth zeigt. Vielleicht könntet das ja Ihr sein?\n\nNehmt Euch etwas Zeit, um ihn kennenzulernen. Ich glaube, Grimmheul wird recht schnell warm mit Euch werden!", sourceObjective = "Stellt eine Bindung zu Grimmheul her.", completion = "Er mag Euch wirklich sehr! Behandelt diesen Welpen mit Liebe und er wird für viele Jahre Euer treuer Weggefährte sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[65594] = { id = 65594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus einem Gnoll einen Elefanten machen", description = "Blöder Verfall denken, ist Boss. Aber ich Boss. Wir jetzt töten. Hab Schleim in Freunde verwandelt.", sourceObjective = "Zerstört 3 Totems des Verfalls.", completion = "Ihr lebt so lang? Gutes Fleisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[65595] = { id = 65595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fauler Apfel", description = "Verrottung lässt Gnolle hungern.\n\nVerrottung verletzt Freunde.\n\nWir jetzt Verrottung töten. Ist Aufgabe von Mohn-Archs.", sourceObjective = "Tötet die Wurzel des Verfalls.", completion = "Führe Gnolle jetzt zu besserer Jagd. Ihr... nicht so schlecht. Aber Gnolle Hunger, und Ihr Fleisch.\n\nGehen. Ich Euch nicht jagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65606] = { id = 65606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen bei den Maruuk", description = "Eure Bemühungen zur Förderung der Interessen des Klans sind nicht unbemerkt geblieben.\n\nKehrt nach Maruukai zurück. Ich habe einige Vorräte vorbereitet, um Euch bei Eurer Zusammenarbeit mit uns weiter zu unterstützen.", sourceObjective = "Sprecht mir Agari in Maruukai.", completion = "Ihr ehrt uns mit Euren Taten. Ich werde den Ältesten von Eurer Arbeit berichten. Nehmt diese Vorräte, auf dass sie Euch auf der Jagd helfen mögen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65613] = { id = 65613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ikonischer wie drakonischer Anblick", sourceObjective = "Nehmt ein Antlitz an.", progress = "Nutzt Euer drakonisches Erbe.", completion = "Oh, Ihr habt ein edles Antlitz, {name}. Einzigartig.\n\nIch weiß nicht, warum sich Euer Antlitz vom Erscheinungsbild eines Drachen unterscheidet. Vielleicht stoßen wir auf die Antwort, wenn wir mehr über Eure Vergangenheit in Erfahrung bringen.\n\nFürs Erste müssen wir uns jedoch auf die anstehende Reise vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65615] = { id = 65615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanes Eindringen", description = "Das Leuchtfeuer vor uns... Ich bin mir sicher, es war noch nicht da, als wir eingesperrt wurden.\n\nZauberei ist nicht meine Stärke, aber ich erkenne arkane Magie, wenn ich sie sehe. Dieselbe Magie hat der blaue Drache in dem Hort angewandt.\n\nEr sagte einen Namen... Malygos. Er hört sich so vertraut an, aber die Lehren des Erdwächters scheinen wie in weiter Ferne. Bruchstückhaft.\n\nFalls uns dieser Malygos in Stasis versetzt hat, wurde vielleicht auch dieses arkane Leuchtfeuer auf seinen Befehl hin platziert.\n\nUntersucht den Bereich und meldet Euch wieder. Vergewissert Euch, dass mit dem Leuchtfeuer keine gegnerischen Verstärkungen herbeigerufen werden können.", sourceObjective = "Untersucht den Arkanstrahl.", progress = "Es liegt mächtige Magie in der Luft. Aber sie ist uralt, verblasst.", completion = "<Azurathel hört konzentriert zu, als Ihr ihm erzählt, was Ihr erlebt habt.>\n\nAlso wurden auch vor den anderen Horten Leuchtfeuer platziert.\n\nUnsere Verbündeten sind in Gefahr. Wir müssen sie erreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65625] = { id = 65625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spießrutenlauf des Kerkermeisters", description = "<Schlundgänger/Schlundgängerin>! Ich habe bereits nach Euch gesucht.\n\nMan erzählt sich, dass sich die Truppen des Kerkermeisters erneut in Torghast sammeln. Ich kann Euch nicht sagen, was sie dort vorhaben, doch es ist bestimmt nichts Gutes.\n\nVielleicht solltet Ihr ihre Pläne durchkreuzen?", sourceObjective = "Betretet das neue Portal im Eingangsbereich von Torghast.", sourceObjectiveStatus = "unverified-source-field" }
quests[65640] = { id = 65640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cervidseele", description = "<Die Cervidseele ist edel und weise. Ihr könnt jetzt die Gestalt des Cerviden nutzen.>", sourceObjective = "Bringt die Cervidseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Cervid. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65649] = { id = 65649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Geschäft", description = "Ah, <Schlundgänger/Schlundgängerin>! Nun, da Ihr einen Weg nach Zereth Mortis gefunden habt, bieten sich jede Menge neue Gelegenheiten.\n\nAlso lasst uns über Geschäftliches reden, ja?\n\nWir haben ein Interesse daran, das Potenzial zu erkunden, das dieser neue Weg eröffnet hat. Ich gehe davon aus, dass Ihr beschaffen könnt, was wir benötigen. Lasst Euch dabei von niemandem aufhalten.\n\nSeid Ihr damit nicht einverstanden, bin ich sicher, dass ich jemand anderen finden kann, der unsere beiden Probleme löst.", sourceObjective = "Sammelt 150 protoplasmische Fäden in Zereth Mortis, während Ihr Euch im Kriegsmodus befindet.", progress = "Ihr kommt nicht mit leeren Händen zurück, habe ich recht?", completion = "Ihr habt Euch gut geschlagen.\n\nHier, ein Zeichen unserer Anerkennung. Eure Bemühungen sind nicht unbemerkt geblieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[65652] = { id = 65652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerufen von der Matriarchin", description = "Seid gegrüßt, {name}.\n\nLasst uns keine unnötigen Worte verlieren. Ihr werdet dringend in Silbermond gebraucht.\n\nWir sehen ein Wiederaufleben der Geißel in Quel'Thalas. Wenn wir die Geißel nicht unter Kontrolle bekommen, werden wir bald überrannt. Wir müssen die Stellung halten!\n\nWir treffen uns in der Halle des Blutes. Dort werdet Ihr umfassend unterrichtet.", sourceObjective = "Trefft Euch mit Lady Liadrin in Silbermond.", completion = "Gut, Ihr habt es geschafft.\n\nLasst uns beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65653] = { id = 65653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg für die Sin'dorei", description = "Die Macht des Ranseurs ist aufgebraucht, aber wir haben gewonnen! Jetzt, da Vorath besiegt ist, wird es vielleicht leichter sein, mit der Geißel fertig zu werden. Dank Euch.\n\nWir treffen uns in der Halle des Blutes. Silbermond ist dankbar für Eure Tapferkeit.", sourceObjective = "Kehrt zu Lady Liadrin in Silbermond zurück.", completion = "Dies ist nicht das Ende der Geißel, aber es ist erfreulich, dass wir die Bedrohung mit solcher Entschlossenheit aus unserem Land vertrieben haben.\n\nSilbermond ist Euch dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[65655] = { id = 65655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen des Wolfs", description = "Dank unserer Spione hat mich ein beunruhigendes Gerücht erreicht.\n\nDie Verlassenen versammeln sich in Tirisfal. Zu welchem Zweck, ist unbekannt. Auch Calia Menethil hat sich dorthinbegeben.\n\nWir müssen mehr darüber erfahren, was sie vorhaben, jetzt, da sie nicht mehr durch die verfluchte Bansheekönigin vereint sind.\n\nGeht, tarnt Euch und schaut, was Ihr herausfinden könnt. Beobachtet alles. Und wenn es eine Möglichkeit gibt, ihr Vertrauen zu gewinnen und mehr zu erfahren, dann tut, worum sie Euch bitten.\n\nIch erwarte ungeduldigst Euren Bericht.", sourceObjective = "Trefft Euch mit Calia Menethil in Brill in Tirisfal.", completion = "<Mit einem Lächeln auf den Lippen mustert Calia Euch einen Moment lang genau.>\n\nIhr werdet gut hierher passen. Und fürchtet Euch nicht: Ich werde Euch nicht vor den anderen hier verraten.\n\nAber Ihr müsst verstehen, dass viele der Verlassenen einst Bürger von Lordaeron waren. Sie versuchen, hier etwas Außergewöhnliches zu tun. Und wenn Ihr mitspielt und ihnen helft, verspreche ich, dass sich die Mühe lohnen wird.\n\nEs wird für ein besseres Azeroth sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65656] = { id = 65656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berufung nach Lordaeron", description = "Jetzt, da die Schattenlande geheilt sind, ist es an der Zeit, unsere Aufmerksamkeit wieder auf die Angelegenheiten in Azeroth zu richten.\n\nDie Verlassenen versammeln sich in den Ruinen des Königreichs Lordaeron. Sie wollen so viel wie möglich von Tirisfal zurückerobern, um die Zerstörungen des Vierten Krieges endlich hinter sich zu lassen.\n\nUnd ich habe vor, ihnen auf jede erdenkliche Weise zu helfen.\n\nIch weiß auch, dass ich der Horde viel zu beweisen habe. Kommt zu mir nach Brill, damit wir den Verlassenen gemeinsam helfen können.", sourceObjective = "Trefft Euch mit Calia Menethil in Brill in Tirisfal.", completion = "Mir lag Brill immer am Herzen.\n\nEs bleibt noch viel zu tun, aber es ist ermutigend zu sehen, welche Fortschritte beim Wiederaufbau erzielt worden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[65657] = { id = 65657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versammelt die Verlassenen", description = "Es ist ermutigend zu sehen, welche Fortschritte beim Wiederaufbau von Brill erzielt worden sind, aber dies ist nur der erste Schritt. Die Ruinen der Hauptstadt sind aufgrund der Seuche unzugänglich.\n\nUnd dabei hoffe ich auf Eure Hilfe.\n\nDie Wiederherstellung eines möglichst großen Teils des Landes erfordert, dass alle zusammen auf ein einziges Ziel hinarbeiten.\n\nEin paar einflussreiche Persönlichkeiten stechen aus den anderen Verlassenen hervor. Bitte helft, sie zusammenzubringen, damit wir uns treffen und die weiteren notwendigen Schritte besprechen können.", sourceObjective = "Bringt die Dunkle Waldläuferin Velonara, Lilian Voss und Apothekermeister Faranell zusammen.", completion = "Es scheint, dass wir bereit sind, anzufangen.\n\nIch glaube, so viele Verlassene waren nicht mehr an einem Ort seit... nun ja, Dunkelküste.\n\nAber jetzt befinden wir uns in unserem eigenen Land und es ist an der Zeit, dass wir uns um unsere eigenen Leute kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[65658] = { id = 65658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dieses Land gehört uns", description = "Die während des Krieges freigesetzte Seuche hat das Land besudelt und die Toten aufgewühlt... noch mehr als sie es ohnehin schon waren.\n\nWir haben hart am Wiederaufbau gearbeitet, aber unser Volk kann seine Vorhaben nicht abschließen, solange es bedroht ist.\n\nMeine erste Pflicht ist, die Sicherheit der Verlassenen zu gewährleisten. Ich werde mich mit den anderen treffen, wie Calia es verlangt. Aber zuerst müsst Ihr mir helfen, einige dieser Verseuchten auszulöschen.", sourceObjective = "Tötet verseuchte Soldaten in Tirisfal.", progress = "Wir müssen den Druck von Brill nehmen, damit wir den Wiederaufbau fortsetzen können.", completion = "Das sollte unseren Wachen etwas Spielraum geben. Bildlich gesprochen, versteht sich.\n\nDanke für die Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[65659] = { id = 65659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seuchentagung", description = "Wir, die Verlassenen, haben seit der Zerstörung von Lordaeron eine Menge durchgemacht. Aber wir sind entschlossen, unsere Heimat zu erhalten.\n\nWarum sollten wir aufgeben, was wir uns so hart erkämpft haben?\n\nCalia ist in mancherlei Hinsicht noch ein Neuling, aber unserem Volk ist sie sehr wohl bekannt. Wie könnte es auch anders sein... als Schwester von Arthas selbst?\n\nIch hoffe, dass wir vorankommen und sie tatsächlich helfen kann. Ihre Stimme könnte Gewicht haben, wenn sie sich wirklich für die Leute einsetzt.", sourceObjective = "Hört den Verlassenen zu.", completion = "Ich habe damit gerechnet, dass meine Anwesenheit Spannungen verursachen würde. Aber ich bin Lilian dankbar für ihre Vermittlung und dafür, dass sie mir die Chance gegeben hat, zu zeigen, dass ich den Verlassenen wahrhaftig helfen möchte.\n\nAber jetzt muss ich es beweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65660] = { id = 65660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Glaubens", description = "Ich habe versprochen, dass ich helfen würde, und das werde ich auch. Wir brauchen diese reine Probe der Seuche, die Lordaeron heimsucht, aber wir dürfen niemand anderen in Gefahr bringen.\n\nKommt mit. Ich werde einen Schild aus heiligem Licht herbeirufen, um uns sicher tief in das verseuchte Gebiet zu bringen, damit wir die Probe sammeln können.\n\nDieser Zauber wird meine volle Konzentration erfordern. Ich vertraue darauf, dass Ihr uns vor allem beschützt, was uns vielleicht aufhalten will.\n\nSeid Ihr dabei?", sourceObjective = "Beschützt Calia in ihrem Schild und sammelt die reine Seuchenprobe.", progress = "Ich hätte daran glauben sollen.", completion = "So etwas sieht man nicht jeden Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[65661] = { id = 65661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anhörung der Verbündeten", description = "Ich hoffe, Calia hat recht, was diese Oberhäupter von Maldraxxus angeht. Und dass sie wissen, wie man mit dieser Art mächtiger Seuche umgeht.\n\nWir haben auch nur noch einen Seuchenfresser übrig, aber Faranell sagt, dass er mehr von ihnen replizieren kann, sofern sie nur stark genug sind, um zu überleben.\n\nLasst uns in die Schattenlande gehen.", sourceObjective = "Sprecht mit Markgräfin Sin'dane in Maldraxxus.", completion = "Ihr habt da ein ziemlich hässliches Beispiel für den unbeherrschten und ungehemmten Ehrgeiz eines Seuchenmachers bei Euch.\n\nIch vertraue darauf, dass der Schöpfer dieser Monstrosität bereits erledigt wurde. Was möchtet Ihr von den Häusern von Maldraxxus erbitten?", sourceObjectiveStatus = "unverified-source-field" }
quests[65662] = { id = 65662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haus der Seuchen", description = "Derjenige mit dem Wissen, nach dem Ihr sucht, ist ein Überlebender des Hauses der Seuchen. Ihr kennt ihn bereits.\n\nSeuchenerfinder Marileth mag nicht der einfachste Gesprächspartner sein, aber er wird wissen, wie mit der Seuche zu verfahren ist.\n\nIhr findet ihn in der Nähe der Ruinen des gefallenen Hauses. Aber seid auf der Hut! Viele Dinge, die dort lauern, könnten Eure Existenz ohne jegliche Vorwarnung beenden.", sourceObjective = "Trefft Euch mit Seuchenerfinder Marileth im Haus der Seuchen.", completion = "Ah, mein Lieblingslehrling!\n\nAber Ihr seht ein wenig blass aus. Seid Ihr sicher, dass Ihr genug Schlaf bekommt?", sourceObjectiveStatus = "unverified-source-field" }
quests[65663] = { id = 65663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Fresser füttern", description = "Das Haus der Seuchen hat Unheil erlitten, genau wie Lordaeron. Ich hoffe, dass unsere Arbeit und unsere Bemühungen hier etwas von dieser Zerstörung rückgängig machen können.\n\nAber zunächst müssen wir weiter in das Haus der Seuchen vordringen, um die Fähigkeiten von Faranells Seuchenfresser zu stärken.\n\nJeder Schleim und jede Kreatur, die Ihr tötet, wird mit Sicherheit zu seiner Stärke beitragen.", sourceObjective = "Tötet Schleime und Seuchenrocs im Haus der Seuchen.", completion = "Der Seuchenfresser sieht schon viel stärker aus. Ich glaube, Apothekermeister Faranell wäre zufrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[65664] = { id = 65664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz der Seuche", description = "Euer kleiner Freund sieht hungrig aus! Keine Sorge, ich weiß genau, was man ihm zu essen geben kann. Bald wird er groß und stark sein und sich mit der Seuche vollfressen können.\n\nEs gibt verschiedene Gebräue, die ihn weiter aufbauen können. Und jede Farbe ist eine andere Geschmacksrichtung!\n\nIch werde die Seuchenprobe, die Ihr mitgebracht habt, tiefer in das Haus der Seuchen bringen, um zu sehen, was es noch zu lernen gibt. Trefft mich dort und lasst Euren Seuchenfresser stilvoll dinieren!", sourceObjective = "Absorbiert verschiedene Gebräue im Haus der Seuchen.", completion = "Habt Ihr das gesehen? Was für eine furchterregende Seuchenprobe Ihr mir doch mitgebracht habt!\n\nSie hat mich am Kopf getroffen und beinahe Eure Freunde getötet, Lehrling. Fantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[65665] = { id = 65665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verkörperung", description = "Was für eine fiese kleine Seuche Ihr mir da gebracht habt, Lehrling. Sie muss von einem wahren Sadisten ausgeheckt worden sein.\n\nUm die Probe zu untersuchen, habe ich ihr Gestalt verliehen. Aber das undankbare Ding wandte sich gegen mich und griff an... völlig grundlos! \n\nEs ist ein bisschen weiter ins Haus hineingeglitten. Ich sage es nur ungern, aber ich glaube, dass dieses Problem beseitigt werden muss, bevor es noch stärker wird... oder größer.\n\nSeht es von der positiven Seite. Wenn Euer Seuchenfresser überlebt, wird er auf Eure besonders schreckliche Form der Seuche eingestellt sein.", sourceObjective = "Erledigt die Lordaeronseuche.", progress = "Habt Ihr schon die Manifestation aus dem Weg geräumt?", completion = "Trotz all der Schwierigkeiten, die uns die Probe bereitet hat, verspüre ich jetzt ein wenig Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[65666] = { id = 65666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Brill", description = "Wir haben unseren Seuchenfresser gestärkt. Jetzt sieht es so aus, als könnte er es mit einer sehr viel größeren Mahlzeit aufnehmen.\n\nGehen wir zurück zu Faranell. Er sagte, er kann seine Eigenschaften replizieren und die Seuchenfresser überall in den Ruinen einsetzen.\n\nDann können wir vielleicht, aber nur vielleicht, unsere Heimat wieder betreten.\n\nHier, nehmt meinen Ruhestein. Er wird Euch zurück nach Brill bringen.", sourceObjective = "Kehrt zu Apothekermeister Faranell außerhalb der Ruinen von Lordaeron zurück.", progress = "Was habt Ihr für mich?", completion = "Wundervoll! Ihr habt es nicht nur geschafft, meinen Seuchenfresser nicht zu verlieren, sondern Ihr habt ihn auch noch stärker denn je zurückgebracht!\n\nJetzt bezeugt die Genialität und Schnelligkeit meiner Maschinen. Es wird mehr als genug Seuchenfresser geben, um sie in ganz Unterstadt einzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65667] = { id = 65667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe von Lordaeron", description = "Die Zeit ist gekommen. Ich bete beim Licht, dass unser Plan funktioniert.\n\nDie Wagen von Apothekermeister Faranell haben jede Menge Seuchenfresser repliziert, und die Fledermäuse sind bereit, sie einzusetzen.\n\nWenn Ihr einen Bereich seht, in dem unsere Truppen noch mehr von dem Heilmittel verbreiten könnten, könnt Ihr ihnen mit einer Fackel ein Zeichen geben.\n\nErhebt Euch in die Lüfte, und lasst uns dieser Seuche ein Ende bereiten. Für Lordaeron... und für die Verlassenen.", sourceObjective = "Sitzt auf eine Schattenfledermaus auf und setzt Seuchenfresser in den Ruinen von Lordaeron ein.", completion = "Wir haben es geschafft. Durch unsere Zusammenarbeit haben wir die Oberfläche von der tödlichen Seuchenwolke befreit.\n\nEs wird mehr Zeit in Anspruch nehmen, die unteren Bereiche von Unterstadt zu säubern, aber das war zumindest ein guter Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[65668] = { id = 65668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der trostlose Rat", description = "Indem wir unser Wissen und unsere Erfahrung gebündelt haben, haben wir den Verlassenen den oberen Bereich von Unterstadt zurückgegeben.\n\nDas war nur möglich, weil wir unser Misstrauen beiseitegelegt und zum Wohle unseres Volkes gehandelt haben. Nun ist es an der Zeit, diesen Rat offiziell zu machen.\n\nWir sind nicht mehr dieselben Untoten, die Sylvanas Windläufer folgten und dienten. Ab sofort führen wir uns selbst, mit demselben Geist der Unabhängigkeit und des Stolzes, den wir zugleich mit unserem freien Willen wiedererlangt haben.\n\nEs ist Zeit für eine neue Zukunft und eine neue Führung.", sourceObjective = "Wohnt der Gründung des neuen Trostlosen Rats bei.", progress = "Es gibt wieder Hoffnung... und frische Luft.", completion = "Ich fühle mich sehr geehrt, dass sie mich als Teil der neuen Führung der Verlassenen akzeptiert haben.\n\nIch schwöre, dass ich mein Bestes geben werde, um unsere Leute zu schützen, ganz gleich, woher sie kommen oder welcher Art des Untotendaseins sie angehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[65669] = { id = 65669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht für Graumähne", description = "Danke Euch für all Eure Hilfe, die zu diesem historischen Moment geführt hat.\n\nIch glaube, es gibt noch andere, die sich für die Ereignisse hier interessieren. Bitte überbringt diesen Brief und meine guten Wünsche, wenn Ihr zu ihnen zurückkehrt.", sourceObjective = "Bringt Calias Brief zu Genn Graumähne in Oribos.", completion = "Sie haben WAS getan?\n\nUnd Calia hat eine Aussprache über die Rückkehr von Gilneas vorgeschlagen?\n\nEure Fähigkeiten sind in der Tat verblüffend, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[65674] = { id = 65674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das für ein Ding?", description = "<Die ominöse Essenz in Euren Händen wirkt, als könnte sie einer Vielzahl von Zwecken dienen. Sie scheint voller Möglichkeiten zu stecken.>\n\n<Vielleicht hat Firim ein paar Antworten.>", sourceObjective = "Bringt die ungeformte Essenz zu Firim in der Höhle des Verbannten.\n\nBereitgestellter Gegenstand:", completion = "Oh, ein äußerst interessanter Fund, Sterblicher.\n\nIch bin bei meinen Forschungen schon einmal auf solches Material gestoßen. Theoretisch kann es das Schicksal verschiedener Objekte verändern, quasi ihr Potenzial freisetzen. Ist das nicht erstaunlich?\n\nIch werde diese Essenz behalten. Im Gegenzug teile ich das Wissen mit Euch, wie Ihr ähnliche Materialien in Euren eigenen Schöpfungen verwenden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65680] = { id = 65680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplanreassimilierung: Herzgebundener Lupin", description = "<Dieser Bauplan enthält das Muster eines neuen Protoformkonstrukts. Präsentiert ihn an einer geeigneten Protoformschmiede, dann wird sie vielleicht eine dieser Kreaturen für Euch instanziieren.>", sourceObjective = "Präsentiert den Bauplan an einer geeigneten Protoformschmiede.\n\nBereitgestellter Gegenstand:", completion = "Exzellent. Mit diesem Bauplan und den richtigen Komponenten kann hier ein neues Lied beginnen, das Euch begleitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[65686] = { id = 65686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Azurblaue Gebirge", description = "Seid gegrüßt, {name}! \n\nPakina und ich sind hier im Auftrag der Kirin Tor und suchen Hilfe.\n\nDie Kirin Tor sind damit beschäftigt, die wilde arkane Magie, die sich überall im Azurblauen Gebirge findet, zu schützen.\n\nKalecgos, der Aspekt des blauen Drachenschwarms und einer unserer Anführer, benötigt Hilfe dabei, den Azurschwurstein erneut zu beanspruchen.\n\nWenn Ihr helfen könnt, reist die Straße weiter, um Glania von den Gesegneten aufzusuchen.\n\nSie kann Euch sagen, wo Eure Hilfe am meisten benötigt wird.", sourceObjective = "Trefft Euch mit Glania von den Gesegneten im Azurblauen Gebirge.", completion = "Hervorragend, ein Abenteurer. Ich kann Euch über die Einzelheiten aufklären, bevor ich lernen muss, wie man... angelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65687] = { id = 65687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagfertige Argumente", description = "Einige der anderen Schüler sind... ziemlich fies.\n\n<Barren reibt über eine frische Wunde auf seiner Schnauze.>\n\nFrüher war das nicht so. Aber dann kam Cygenoth und sagte: \"Wir sollten Stärke über alles andere stellen.\" Jetzt kämpfen alle die ganze Zeit.\n\nIch will mich ja wehren! Aber ihre Bälge sind zu dick... und ich bin zu klein.\n\nAber Ihr nicht! Ihr kämpft bestimmt andauernd gegen Fieslinge. Vielleicht könnt Ihr ja helfen?", sourceObjective = "Tötet 12 Weltenbrecherdrachkin.", progress = "Die Weltenbrecher sind nicht alle gemein. Versprochen!", completion = "Diese krummschuppigen Trottel werden niemandem mehr wehtun! Der Erdwächter dankt Euch!\n\nOh. Und ich. Ich danke Euch auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[65688] = { id = 65688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit Kalecgos", description = "Ich fürchte, wir werden unsere Aufmerksamkeit teilen müssen. Die Primalistenbedrohung im Osten muss unter Kontrolle gebracht werden.\n\nIch muss Euch darum bitten, an meiner statt zu den Azurarchiven zu reisen und Kalecgos dabei zu unterstützen, den Azurschwurstein neu zu beanspruchen.\n\nIhr werdet einige Vorräte einpacken müssen, die Euch dabei helfen werden, mit den ganzen Geschehnissen dort fertig zu werden.\n\nSprecht mit unserem Portalrüstmeister. Dort solltet Ihr etwas bekommen können, das Euch auf Eurem Wege hilft.\n\nViel Glück, {name}. Kalecgos wird die Hilfe zu schätzen wissen.", sourceObjective = "Holt die Tasche nützlicher Waren und trefft Kalecgos am Fuße der Azurarchive.", progress = "Ich bin erleichtert, Hilfe zu bekommen. Ich weiß, dass Khadgar und die anderen mit den Primalisten recht beschäftigt sein müssen.", completion = "Khadgar verfügt über die Weisheit, seine Anstrengungen in Richtung der Primalisten umzulenken.\n\nAber jetzt... haben wir hier eine Menge Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[65689] = { id = 65689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vielen Abbilder von Kalecgos", description = "Schön, Euch offiziell kennenzulernen, {name}. Mein Name ist Kalecgos, Erzmagier der Kirin Tor und Aspekt des blauen Drachenschwarms.\n\nIch habe Schwierigkeiten bei der Wiederherstellung der Azurarchive, um den Azurschwurstein erneut zu beanspruchen. Ich könnte ein zusätzliches Paar physischer Hände gut brauchen.\n\nIch bin gerade oben in den Archiven selbst. Es ist mir gelungen, den Pylon draußen zu reaktivieren, das sollte Euch erlauben, hier heraufzukommen.", sourceObjective = "Nutzt den Kristallpylon, um zu den Azurarchiven zu gelangen.", completion = "Fangen wir an! Es ist unbedingt notwendig, den Azurschwurstein wiederzubeschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65690] = { id = 65690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befürchtungen eines Kultisten", description = "Eine weitere Außenseiterin kam gestern hier an. Sie nannte sich \"Abgesandte\" des roten Drachenschwarms und bat um eine Audienz bei unserem Anführer, der Stimme Neltharions.\n\nDoch die Stimme wurde furchtbar wütend. Er sagte, dass der Erdwächter uns auf die Probe stellt, und dass wir sie hinrichten müssen!\n\nIch weiß, dass wir Fremden nicht trauen sollen, aber deshalb müssen wir sie ja nicht gleich töten! Bitte helft mir, sie zu retten.", sourceObjective = "Findet Ayasanth im Schwelenden Horst.", completion = "Dieser Schlüpfling bat um Eure Hilfe?\n\n<Ayasanth atmet erleichtert aus.>\n\nVielleicht können wir die Weltenbrecher doch retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65691] = { id = 65691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatten seiner Schwingen", description = "Die Stimme von Neltharion hält sich weiter unten auf und verbreitet Lügen unter ihren Anhängern.\n\nEr scheint wie ich der Drachenbrut anzugehören, aber er spricht gebrochenes Drakonisch, als wäre er ein Ungeschuppter.\n\nIch vermute ein falsches Spiel, womöglich eine Illusion. Wenn wir ihn unterwerfen können, wird die Wahrheit sicherlich ans Licht kommen.", sourceObjective = "Stellt Cygenoth, Stimme von Neltharion, zur Rede.", completion = "Heute haben wir die letzte Glut des Schattenhammerklans ausgestampft. Aber die Weltenbrecher sind eine andere Geschichte. Diese Schuppengeborenen werden neue Erklärungen für ihr Unglück, neue Mythen und neue Anführer finden.\n\nMeine Art und ich werden sie im Auge behalten. Sollte sich eine weitere Stimme erheben, werden wir einschreiten.\n\nIhr habt heute Gutes getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[65700] = { id = 65700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernkontrolle", description = "Ihr kommt gerade zur rechten Zeit.\n\nAnscheinend ist mir vor wenigen Augenblicken eine seltsame Kreatur in die Falle gegangen. Ich wage nicht, sie mir näher anzusehen... doch Ihr könnt das für mich übernehmen.\n\nNehmt Pocopoc mit. Ihr könntet auf Geheimnisse stoßen, die es zu entschlüsseln gilt.", sourceObjective = "Untersucht die seltsame Kreatur vor der Höhle des Verbannten.", completion = "Pocopoc ist faszinierend, nicht wahr? Ich frage mich, zu wie viel mehr er noch imstande ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[65701] = { id = 65701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewahrung, Verstärkung oder Verheerung", description = "Falls es stimmt, was diese Drachen sagen, dann erwartet uns eine große Schlacht. Wir brauchen Eure Konzentration und Eure Stärke, <Rufer/Ruferin>.\n\nEs ist an der Zeit, dass Ihr Eure Kampfspezialisierung wählt. Werdet Ihr Eure Verbündeten bewahren oder Eure Feinde verheeren? \n\nUm Eure Kampffertigkeiten bis auf das Schärfste zu schleifen, wählt Verheerung.\n\nUm Euer Heilpotenzial zu maximieren, wählt den Weg der Bewahrung.\n\nUm Eure Flügelgefährten zu ermächtigen, wählt Verstärkung.\n\nJede Spezialisierung sollte Euch gut dienen. Und vergesst nicht, Ihr könnt sie später noch ändern oder anpassen.", sourceObjective = "Wählt eine Spezialisierung.", completion = "Hervorragende Wahl.\n\nDenkt daran, dass Ihr Eure Spezialisierung jederzeit überdenken und Eure Fähigkeiten anpassen könnt, wenn Ihr Euch nicht gerade im Kampf befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[65702] = { id = 65702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Wahnsinn getrieben", description = "Die Azurarchive waren einst der Ort, wo die blauen Drachen sich versammelten, um über Magie zu diskutieren.\n\nNun bin ich hier der einzige meiner Art.\n\nVon hier aus werden die gewaltigen Leylinien unter dem Azurblauen Gebirge beaufsichtigt, aber dieser Ort und seine Diener sind außer Kontrolle geraten.\n\nIch glaube, wenn wir wieder Ordnung in diesen Ort bringen, kann ich den Azurschwurstein neu beanspruchen.\n\nDie verschiedenen Konstrukte und Elemente sind voller instabiler arkaner Energie, die umgeleitet werden muss.\n\nZerstört sie und sammelt ein, was Ihr könnt.", sourceObjective = "Bergt 40 Portionen instabiler Arkanenergie.", progress = "Die Archive befinden sich für die meisten ihrer Wächter in einem Zustand der ständigen Erneuerung. Wir müssen diesen Fluss wiederherstellen.", completion = "Hervorragende Arbeit. Diese Menge an instabilem Arkana zu entfernen, hat bereits genügt, um die Schöpfungen hier zu besänftigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65703] = { id = 65703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenlande (60) E" }
quests[65704] = { id = 65704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenlande (60) E" }
quests[65705] = { id = 65705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenlande (60) E" }
quests[65709] = { id = 65709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanes Stutzen", description = "Wir können den Schwurstein in den Azurarchiven nicht aktivieren, bis wir das Problem mit der außer Kontrolle geratenen Leyenergie hier behoben haben.\n\nZwei der drei drakonischen Runen, die sie kontrollieren sollen, werden von instabilem Arkana unterdrückt.\n\nIch entschuldige mich, dass dies aufgrund von Khadgars Verantwortungen und dem Nichterscheinen meiner Leute nun Euch zufällt.\n\nIn der Tasche nützlicher Waren, die Ihr habt, sollte ein Leyszepter sein.\n\nBenutzt es, um die Runen in der Nähe zu reparieren.", sourceObjective = "Sucht in der Tasche nützlicher Waren nach dem Leyszepter und nutzt es, um zwei Plattformen zu reparieren.", progress = "Mit dem Leyszepter solltet ihr die Runen in der Nähe richtig ausrichten und konfigurieren können.", completion = "Hervorragende Arbeit. Anscheinend können uns diese Runen zu den Archiven hoch transportieren.\n\nIch glaube, dort befindet sich unser letztes Problem...", sourceObjectiveStatus = "unverified-source-field" }
quests[65711] = { id = 65711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Donner rauben", description = "Ihr seid das! Ohn'ahra sei Dank. Ich habe so getan, als wäre ich verletzt, um den nächsten Grobian in die Irre zu führen, der sich hierher traut. Uff... die Huflecker haben mich mit einem Bindungszauber belegt. Den werde ich noch brechen.\n\nSie halten Lizi in der Höhle gefangen. Bitte befreit sie. Ich komme hier schon allein klar.\n\nTut, was Ihr tun müsst.", sourceObjective = "Tötet die Sturmextraktoren und befreit Lizi das Donnerrückgrat aus dem Lager der Kaighan.", progress = "Wer Lizi auch nur eine Schuppe zerkratzt, wird dafür büßen!", completion = "<Radiya ist ungewöhnlich still und zittert beim Anblick des gequälten Wildtiers leicht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65717] = { id = 65717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leitmotive", description = "<Ein kleines Objekt zieht Euren Blick auf sich. In ihm funkelt Progenitormagie, uralt und doch... auf seltsame Art edler.>\n\n<Sanfte Schwingungen und Töne sind in dieses Gerät verwoben. Der sich wiederholende Refrain scheint fast... sprechen zu wollen?>\n\n<Firim hätte sicherlich großes Interesse daran.>", sourceObjective = "Bringt das Echo des Almanachs zu Firim in der Höhle des Verbannten.\n\nBereitgestellter Gegenstand:", completion = "Bei den Ersten... Ihr habt ein weiteres Mal einen außergewöhnlichen Fund gemacht. Es ist Euch nach Eurem Sieg über den Kerkermeister in die Hände gefallen? Wie merkwürdig.\n\nEs scheint mir fast, als wollte es... kommunizieren. Was das für Folgen haben könnte... Ah! Verzeiht, da geht der Wissenschaftler mit mir durch. Ich befürchte, hier muss ich komplexere Forschungen durchführen.\n\nNehmt das hier im Gegenzug. Es handelt sich um eine meiner ersten Entdeckungen. Vermutlich könnt Ihr sie besser gebrauchen als ich.\n\nHabt Dank, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[65725] = { id = 65725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergrabene Bufonid", progress = "Der große Bufonid unter dem Schlamm regt sich immer noch nicht.\n\nEr muss doch irgendeine Vorliebe haben. Habt Ihr ein bisschen Fleisch dabei? Das lockt ihn vielleicht hervor.", completion = "Habt Dank, {name}. Mal sehen, ob das funktioniert." }
quests[65726] = { id = 65726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergrabene Bufonid", progress = "Wenn Fleisch und Honig die Kreatur nicht aus dem Wasser locken konnten, sollten wir unsere Herangehensweise überdenken.\n\nBringt mir ein bisschen Schleierstoff. Ich werde daraus ein Netz anfertigen. Vielleicht ist das etwas effektiver.", completion = "Habt Dank, {name}. Gehen wir es an, zum Wohle von Krümel, wenn nicht für unsere eigene Neugier." }
quests[65727] = { id = 65727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergrabene Bufonid", description = "Habt Ihr schon einmal innegehalten und die Bufoniden beobachtet?\n\nEin prächtiges Exemplar liegt im Wasser verborgen. Still, geduldig, unbeweglich. Der weise Krümel kommt ganz nach ihm. Sie ähneln sich sehr. Ich habe das Gefühl, dass Krümel den großen Bufoniden gerne aus der Nähe sehen würde.\n\nVielleicht lässt sich die Kreatur mit Honig von den Vespiden hier in Zereth Mortis hervorlocken. Könntet Ihr welchen sammeln?", sourceObjective = "Sammelt 15 Portionen Vespidenhonig von Vespiden in Zereth Mortis.", progress = "Habt Ihr den Honig?", completion = "Ich danke Euch, {name}. Dann wollen wir doch mal sehen, ob der Bufonid nun herauskommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65728] = { id = 65728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergrabene Bufonid", progress = "Da die Falle nicht funktioniert hat, sollten wir uns einen Köder überlegen, für den sich dieser asketische Bufonid interessieren könnte.\n\nVielleicht frisst er ja gern Fisch? Bitte bringt uns welchen.", completion = "Danke, {name}. Hoffen wir, dass das klappt." }
quests[65729] = { id = 65729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergrabene Bufonid", progress = "Mir gehen langsam die Ideen aus. Worauf könnte unser schüchterner Freund nur Lust haben?\n\nProbieren wir es mit Fleisch von anderen Kreaturen in Zereth Mortis. Etwas muss seine Aufmerksamkeit einfach erregen!", completion = "Habt Dank, {name}. Mal sehen, ob wir damit Ergebnisse erzielen." }
quests[65730] = { id = 65730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergrabene Bufonid", progress = "Was könnten wir sonst noch ausprobieren, um den Bufoniden aus seinem Versteck zu locken?\n\nVielleicht wissen die Jiro ja mehr. Hier in der Nähe verkaufen sie angeblich Früchtegebäck. Bringt uns doch bitte eines davon.", completion = "Danke, {name}. Vielleicht hat unser Bufonidfreund ja nur einen ausgefalleneren Geschmack." }
quests[65731] = { id = 65731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergrabene Bufonid", progress = "Hmmmmm...\n\nMein Freund, mir sind die Ideen fast ausgegangen. Wir haben all die verlockenden Aromen von Zereth Mortis ausgeschöpft.\n\nIch habe mir stundenlang den Kopf darüber zerbrochen, was den Gaumen in meinem Leben bisher schon alles verwöhnt hat. Mir fällt lediglich noch ein Geschmackserlebnis ein, das ich außerhalb von Zereth Mortis hatte:\n\nSüße Biomelonen.\n\nAuf dem großen Marktplatz von Tazavesh verkaufte mein lieber Freund sie einst. Vielleicht sind sie ja noch dort? Ihr müsst Euch jedoch erst Zugang zur Stadt verschaffen, falls Ihr das nicht bereits habt.", completion = "Danke, {name}. Diese Frucht bringt lange vergessene Erinnerungen zurück.\n\nDoch ist sie nicht für mich gedacht. Wollen wir doch mal sehen, ob unser verborgener Bufonidfreund ihr widerstehen kann." }
quests[65732] = { id = 65732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geduldige Bufonid", description = "Seht doch, eine weitere eindrucksvolle Kreatur von Zereth Mortis! Bei dem Funkeln in ihren Augen gehe ich fast davon aus, dass sie uns die ganze Zeit zum Narren gehalten hat.\n\nGeduld zahlt sich aus. Krümel freut sich.\n\nGroßartige Arbeit, <Schlundgänger/Schlundgängerin>.", sourceObjective = "Danke, {name}. Die Kreatur wirkt relativ freundlich auf mich, und ich glaube, sie mag Euch! Gewiss werdet Ihr Euch gut um sie kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[65735] = { id = 65735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Custos", description = "Bei einem zuvor stabilen Automa treten ungewöhnliche Fehlfunktionen auf. Es greift Erleuchtete auf der Straße außerhalb der Huld des Pilgers an.\n\nEs ist von großer Wichtigkeit, dass die Straßen für unsere Pilger sicher bleiben.\n\nRafiq hat die Auslöschung dieser Bedrohung zur höchsten Priorität erklärt.", sourceObjective = "Vernichtet Custos.", completion = "Ich begreife sein Verhalten nicht, doch jetzt sind wir alle wieder sicher. Diese Belohnung wird Euch zugutekommen, wenn Ihr meine besseren Stücke erstehen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65748] = { id = 65748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für die Anstrengungen", description = "Die Ausrüstung, die ich zur Verfügung stelle, ist dem Segen der Ersten sowie den... Anstrengungen vieler anderer Reisender geschuldet.\n\nWir alle müssen uns um jene kümmern, die uns nachfolgen.\n\nSammelt alle Vorräte ein, die Ihr während Eurer Erkundungen in Zereth Mortis finden könnt. Haltet die Augen offen, oft sind sie an rätselhaften Orten versteckt. Kehrt dann wieder zu mir zurück. Ich werde sie zukünftigen Reisenden zur Verfügung stellen.", sourceObjective = "Findet 10 Vorräte der Erleuchteten in Truhen, Nestern, Relikten und anderen Behältern in Zereth Mortis.", progress = "Habt Ihr etwas für mich?", completion = "Grüße, Reisender! Was habt Ihr gefunden? Ah, das wird vielen anderen notdürftigen Reisenden helfen. Ihr habt meinen Dank und auch den ihren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65749] = { id = 65749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nötige Ausrüstung", description = "Ich stehe seit einiger Zeit in Kontakt mit Rafiq, einem meiner Kollegen. Allein dank unserer gemeinsamen Bemühungen war er in der Lage, nützliche Gegenstände zu beschaffen.\n\nÜberbringt Rafiq meine neuesten Forschungsnotizen und versucht, Euch gut mit ihm zu stellen. Im Lauf der Zeit sollte er Euch mit besserer Ausrüstung versorgen können.", sourceObjective = "Sammelt Firims Forschungsnotizen und überbringt sie Rafiq.", progress = "Was habt Ihr mir da mitgebracht?", completion = "Ihr habt meinen Dank, {name}. Nehmt dieses Geschenk für Eure zukünftigen Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65750] = { id = 65750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtbeinige Plage", description = "{class}!\n\nIch brauche Eure Hilfe, wenn Ihr bereit seid...\n\nDiese gemeinsame Expedition sollte die einzigartigen Arachniden in dieser Gegend studieren, aber wie Ihr sehen könnt, ist unser Plan gescheitert.\n\nWas wir ursprünglich für eine evolutionäre Anpassung hielten, ist stattdessen eine Perversion der natürlichen Ordnung durch die Primalisten!\n\nIch nehme meine Verantwortung als Naturschützerin ernst, aber die Zeit des Studiums lebender Exemplare ist vorbei. Wir können nicht zulassen, dass sich ihre Perversion ausbreitet. Stattdessen können wir ihre Leichen erforschen.\n\nWerdet Ihr uns dabei helfen?", sourceObjective = "Tötet 10 Schaudernetzschleicher oder Schaudernetzkriecher und 3 Pfleger der Primalisten im Schaudernetztal.", completion = "Bedauernswert, aber notwendig. Wir durften nicht zulassen, dass sie sich ausbreiten.\n\nIch denke, wir haben alles über sie erfahren, was wir können.", sourceObjectiveStatus = "unverified-source-field" }
quests[65751] = { id = 65751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plattformanpassungen", description = "Die letzte arkane Störung scheint hier oben zu sein.\n\nIch werde die Leyenergien weiter angleichen. Benutzt etwas von dem Arkana, das Ihr zuvor geborgen habt, um die Unterbrechungen hier auszugleichen.", sourceObjective = "Bannt 3 Einheiten instabiler Arkanenergie an der Spitze der Azurarchive.", progress = "Braucht Ihr etwas?", completion = "Sehr gute Arbeit! Ich kann spüren, wie die Leylinien unterhalb dieses Ortes zu heilen beginnen. Wir haben es fast geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[65752] = { id = 65752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Störenfriede", description = "Eine große Anzahl Manawyrms absorbiert die wilde arkane Magie, die den Archiven entströmt.\n\nDie Rate, mit der sie das tun, stört das Gleichgewicht der Leylinien... was verhindert, dass der Azurschwurstein wiedererlangt werden kann.\n\nIch werde etwas von dem instabilen Arkana nutzen, das Ihr eingesammelt habt, um eine Art Haken zu bilden.\n\nNutzt ihn, um einige Wyrms zu erledigen. Die kurze Verzögerung wird genug für mich sein, um die Energien unten anzupassen.", sourceObjective = "Tötet 6 schlemmende Wyrms.", completion = "Die Kirin Tor werden sicherstellen, dass man sich ordentlich um diese Archive kümmert, wenn dies vorbei ist. Vielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[65758] = { id = 65758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grungir der Entdecker", description = "{name}! Mein Kollege aus der Forscherliga, Grungir Eisenschnauze, war nicht unter jenen, die Ihr gerettet habt. Zunächst hatte er sich den Weg freigekämpft, aber als er sah, wie wenige von uns es rausgeschafft hatten, kehrte er um und ging direkt wieder rein! Alleine!\n\nDieser Trottel ist ebenso mutig wie impulsiv. So ein Schicksal hat er nicht verdient.\n\nBitte findet ihn.", sourceObjective = "Findet Grungir Eisenschnauze.", completion = "Gut, zur Abwechslung mal ein Gesicht mit der richtigen Anzahl an Augen zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65760] = { id = 65760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Dienst melden", description = "Ich habe bisher nur in Büchern über die Djaradin gelesen.\n\nUralte Rivalen der Drachen, mächtige Riesen und Herrscher über Erde und Lava... wild entschlossen, die Drachen bis zur Auslöschung zu jagen.\n\n<Sendrax runzelt die Stirn beim Anblick des fernen Vulkans.>\n\nMein Ausbilder sagte, sie wären nicht mehr gesehen worden, seit die Drachen verschwunden sind, da sie tief in der Erde schlafen.\n\nSollten sie erwacht sein, ist jeder Welpling auf diesen Inseln in Gefahr!\n\nWir sollten uns schleunigst zu Kommandant Lethanak beim Drachenherzaußenposten begeben.", sourceObjective = "Trefft Euch mit Kommandant Lethanak beim Drachenherzaußenposten.", completion = "Ich nehme jede Verstärkung, die ich bekommen kann.\n\nWir müssen schnell handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[65761] = { id = 65761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Abenteuer als erwartet", description = "<Godolotos Blick ist starr und vorwurfsvoll. Sie hustet.>\n\n<Vielleicht kann Euch die Ohuna helfen, Radiya zu finden und zu retten.>", sourceObjective = "Nutzt Godoloto, um Radiya zu finden und zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65762] = { id = 65762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mausoleum der Ersten: Schwer wiegt die Krone", description = "Anduins Klinge ist ein mächtiger Fokus für den Kerkermeister. Wenn wir die Fragmente dieser Waffe für uns beanspruchen, kann ich einen Pfad direkt zum jungen König öffnen.\n\nVier Fragmente sollten genügen. Damit können wir Anduin endgültig aus den Fängen des Kerkermeisters befreien.", sourceObjective = "Sammelt 4 Schwertfragmente von Anduin im Mausoleum der Ersten auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Vier Schwertfragmente sollten es uns ermöglichen, seine Kammer zu betreten.", completion = "Das sollte uns helfen, direkt zu Anduin gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65763] = { id = 65763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mausoleum der Ersten: Schwer wiegt die Krone", description = "Anduins Klinge ist ein mächtiger Fokus für den Kerkermeister. Wenn wir die Fragmente dieser Waffe für uns beanspruchen, kann ich einen Pfad direkt zum jungen König öffnen.\n\nVier Fragmente sollten genügen. Damit können wir Anduin endgültig aus den Fängen des Kerkermeisters befreien.", sourceObjective = "Sammelt 4 Schwertfragmente von Anduin im Mausoleum der Ersten auf dem Schwierigkeitsgrad 'Heroisch'.", progress = "Vier Schwertfragmente sollten es uns ermöglichen, seine Kammer zu betreten.", completion = "Das sollte uns helfen, direkt zu Anduin gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65764] = { id = 65764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mausoleum der Ersten: Schwer wiegt die Krone", description = "Anduins Klinge ist ein mächtiger Fokus für den Kerkermeister. Wenn wir die Fragmente dieser Waffe für uns beanspruchen, kann ich einen Pfad direkt zum jungen König öffnen.\n\nVier Fragmente sollten genügen. Damit können wir Anduin endgültig aus den Fängen des Kerkermeisters befreien.", sourceObjective = "Sammelt 4 Schwertfragmente von Anduin im Mausoleum der Ersten auf dem Schwierigkeitsgrad 'Normal'.", progress = "Vier Schwertfragmente sollten es uns ermöglichen, seine Kammer zu betreten.", completion = "Das sollte uns helfen, direkt zu Anduin gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65768] = { id = 65768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Späher", description = "Die Truppen des Kerkermeisters kontrollieren den Großteil von Zereth Mortis, doch es lauern da draußen noch weitere Gefahren.\n\nIch habe Späher losgeschickt, welche die Umgebung erkunden und potenzielle Gefahren lokalisieren sollen.\n\nSprecht mit den einzelnen Spähern und hört Euch ihre Meldungen an. Erstattet mir dann Bericht.", sourceObjective = "Sprecht mit den Spähern in Zereth Mortis.", progress = "Was habt Ihr herausgefunden?", completion = "Mit diesen Informationen können wir unseren nächsten Schritt planen. Habt Dank, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[65769] = { id = 65769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisige Spinnweben", description = "Viele meiner Freunde und Kollegen wurden gefangen genommen, als die Arachniden und ihre Primalistenmeister angriffen.\n\nIch habe gesehen, wie sie mit gefrorenen Spinnweben gefesselt und verschleppt wurden. Ihnen droht ein Schicksal, das ich mir gar nicht ausmalen mag.\n\nBitte befreit so viele von ihnen wie möglich!", sourceObjective = "Befreit 6 eingesponnene Überlebende im Schaudernetztal.", completion = "Ich danke Euch, {name}. Ich hatte schon befürchtet, niemanden von ihnen je wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65770] = { id = 65770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Versprechen ist ein Versprechen", description = "Die Tiere scheinen sich in Eurer Nähe wohlzufühlen. Das ist ein gutes Zeichen für Euren Geist.\n\nNun... könnt Ihr ein Geheimnis für Euch behalten? Ich möchte Euch einer Freundin vorstellen. Niemand weiß von ihr.\n\nIhr müsst mir zuerst versprechen, dass das zwischen uns bleibt. Meine Ohn würde mich von den Ebenen verbannen, wenn sie es herausfände.", sourceObjective = "Versprecht Initiandin Radiya, ihr Geheimnis zu bewahren.", completion = "<Togotsengs Ohuna starrt Euch an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65771] = { id = 65771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gunst der Ersten", description = "Der Angriff der Truppen des Kerkermeisters ist ein Zeichen! In der Vergangenheit strebte einer von uns nach dem verbotenen Wissen der Ersten. Dafür haben wir ihren Zorn auf uns gezogen und den Schutz verloren, den sie uns einst boten.\n\nWir müssen für die Vergehen unseres Volkes sühnen.\n\nNehmt dieses Räucherwerk. Geht hinaus in das Veld und verbrennt es als Opfergabe an die Ersten. Ich hoffe, sie werden uns vergeben.", sourceObjective = "Verbrennt Räucherwerk der Erleuchteten im Großen Veld.", completion = "Mögen die Ersten unsere Opfergaben als Buße für unsere Verfehlungen annehmen.\n\nHabt Dank, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[65772] = { id = 65772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nötige Nahrungsbeschaffung", description = "Die Angriffe der Schlundgebundenen wie auch Eure Anwesenheit hier lassen unsere Nahrungsvorräte zur Neige gehen. Ich sage das nicht gerne, doch am schnellsten stocken wir unsere Ressourcen mit Wild aus der Region auf.\n\nEs ist schrecklich, dass es so weit kommen musste, aber wir haben keine Wahl. Streckt einige Wildtiere nieder, damit wir wieder zu essen haben.", sourceObjective = "Sammelt 15 Portionen latentes Protein von Raptoras, Cerviden und Lupinen im Großen Veld und Umgebung.", progress = "Habt Ihr uns die nötigen Vorräte gebracht?", completion = "Vielen Dank. Wir wissen Eure Mühen sehr zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65773] = { id = 65773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solomission", description = "Es ist wohl an der Zeit, dass Ihr Euch ganz allein beweist.\n\nMöglicherweise ist der Konflikt kontinuierlicher Natur, doch Ihr müsst ihn ohne Unterstützung auf Euch nehmen. Manchmal muss man an der Seite des Feindes kämpfen, um seine Taktik zu durchschauen. Dies könnte Eure Gelegenheit sein.\n\nViel Glück.", sourceObjective = "Schließt 5 Runden im gemischten Einzel ab.", completion = "Ausgezeichnet. Ihr kämpft erbittert, um ein Stück Land zu beanspruchen. Der Beobachter wird das faszinierend finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[65774] = { id = 65774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Katalysator erwacht", description = "Spürt Ihr es, <Abenteurer/Abenteurerin>? Hoch über den Katalysatorgärten vibriert neue Energie im Schöpfungskatalysator.\n\nDiese Energie wird die Welt verändern. Ihr müsst sie Euch sofort zunutze machen.", sourceObjective = "Reist zu den Katalysatorgärten und benutzt den Schöpfungskatalysator.", completion = "Ihr haltet die Macht der Schöpfung in Euren Händen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65775] = { id = 65775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solostrategie", description = "Ihr habt den Testkampf überstanden.\n\nBei diesen Kämpfen ist aber noch Luft nach oben. Versucht es erneut.\n\nKehrt zurück, wenn Ihr fertig seid.", sourceObjective = "Schließt 15 Runden im gemischten Einzel ab.", completion = "Ausgezeichnet. Ihr kämpft erbittert, um ein Stück Land zu beanspruchen. Der Beobachter wird das faszinierend finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[65777] = { id = 65777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammbedeckte Halskette", description = "<Die uralten Muster auf der Halskette sind schwer zu entziffern, aber sie scheint aus Tierhaut und geschnitzten Knochenfragmenten zu bestehen.\n\nVielleicht kann Euch ein erfahrener Jäger mehr über den Wert dieses Objekte erzählen.>", sourceObjective = "Macht jemanden ausfindet, der sich mit der Ebenenjagd und handgefertigten Artefakten auskennt.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[65778] = { id = 65778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mitbringsel für den Kreischerschwarm", description = "Seid Ihr bereit, Eure schauspielerischen Talente unter Beweis zu stellen, {name}?\n\nWas? Keine solchen Talente? Dann ist es ja gut, dass ich Euch aus den Materialien, die Ihr gesammelt habt, eine federführende Kreischerschwarmverkleidung gefertigt habe!\n\nSegallia und ich brauchen noch Zeit, um das letzte \"Ei\" zu bauen, das die Matriarchin ausschalten wird. Ich habe allerdings eine kleinere Version als Prototyp gebaut, die Ihr an der Köchin ausprobieren könnt.\n\nUnd keine Bange! Unter all den Federn seid Ihr 12% besser vor diesen Explosionen geschützt!", sourceObjective = "Tragt Eure Verkleidung und verwendet das \"Prototypei\" gegen die Chefköchin der Matriarchin.", completion = "Ihr habt tolle Arbeit geleistet und in der Verkleidung auch noch toll ausgesehen!\n\nEndlich bereit, dieser schrecklichen Bedrohung den Schnabel zu stutzen?", sourceObjectiveStatus = "unverified-source-field" }
quests[65779] = { id = 65779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Ebenen", description = "Der grüne Drachenschwarm ist in ihre Gärten in den nahen Ebenen zurückgekehrt. Königin Alexstrasza wünscht, dass Ihr Euch mit Merithra des Traums in Verbindung setzt.\n\nDie Zentauren dieser Ebenen sind stolze Jäger. Um in die Smaragdgärten zu gelangen, müsst Ihr mit ihnen zuerst diplomatische Beziehungen eingehen.\n\nZeigt Respekt, aber keine Schwäche.", sourceObjective = "Trefft die Späherin der Shikaar auf den Ebenen von Ohn'ahra.", progress = "<Tomul mustert Euch von oben bis unten mit zurückhaltender Neugier.>\n\nWas ist Euer Anliegen auf den Ebenen?", completion = "Dann dient Ihr als Bote der Drachen. Wie die Zeiten sich ändern...", sourceObjectiveStatus = "unverified-source-field" }
quests[65780] = { id = 65780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewährungsprobe", description = "Ein Geschenk der Drachen mag einige Zentauren beeindrucken, aber Klan Shikaar muss sehen, wie gut Ihr jagt.\n\nEiner unserer Jagdtrupps brachte gerade einen Protodrachen zu Boden, dem die Kraft der Flamme innewohnt. Beweist uns Euren Wert und helft dem Trupp, ihn zu töten.", sourceObjective = "Tötet den lodernden Protodrachen.", progress = "Ihr scheint ganz gut alleine klarzukommen. Aber der Eindruck kann täuschen.", completion = "Ihr seid ein besserer Kämpfer, als ich dachte.", sourceObjectiveStatus = "unverified-source-field" }
quests[65782] = { id = 65782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter Schloss und Riegel", description = "Als wir Gerüchte eines Todesschwingenkults gehört haben, befahl Majordomus Selistra mir, diese ehemaligen Schuppengeborenen wieder bei uns aufzunehmen. Wir hatten gehofft, dass es sich einfach nur um ein Missverständnis handelte.\n\nOffensichtlich lagen wir falsch.\n\nWir müssen uns um ihren Anführer kümmern, aber zuerst muss ich aus diesem Käfig entkommen. Findet den Schlüssel und bringt ihn mir.", sourceObjective = "Beschafft den Weltenbrecherzellenschlüssel und befreit Ayasanth.", progress = "Ich muss schon sagen: Dieser Käfig wird langsam etwas ermüdend.", completion = "Ich wurde zwar gefangen genommen, doch die Weltenbrecher spucken im Vergleich zu dem Schattenhammer kaum einen Funken. Zumindest eine Sache, für die ich ein bisschen dankbar sein kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[65783] = { id = 65783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen an unserem Feuer", description = "Ihr habt Seite an Seite mit unseren Jägern gekämpft und Euch einen Platz an unserem Feuer verdient.\n\nUnsere Khan ist beim Jagdposten im Sumpf und bereitet unsere nächste Karawane vor. Ich werde sie über Eure Ankunft und Euer Anliegen benachrichtigen.\n\nDen Weg findet Ihr gewiss selbst.", sourceObjective = "Trefft Späherin Tomul am Baumschrittaußenposten.", completion = "Ihr Fremde scheint es Euch zur Gewohnheit gemacht zu haben, Euch in die Angelegenheiten anderer einzumischen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65784] = { id = 65784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prächtige Otter", description = "Am Flussufer im Nordosten befindet sich eine Verzweigung von Otterhöhlen. Einige der Otter dort tragen den Segen des Flusses in sich und sind zu beeindruckender Größe herangewachsen.\n\nAus Respekt möchte ich nicht, dass Ihr sie jagt. Ihr sollt sie stattdessen lebendig herbringen, damit wir ihnen die Ehre entgegenbringen können, die sie verdient haben.", sourceObjective = "Bringt 3 gigantische Flussotter zum Klan Aylaag.", progress = "Vergesst nicht, dass Ihr sie lebend zurückbringen müsst.", completion = "Was für edle Wesen. Wir werden alles nutzen, was sie uns zu bieten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[65788] = { id = 65788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaziergang mit Geistern", description = "Diese Ruinen zurückzuerobern, bedeutet den Verlassenen sehr viel. Insbesondere seit dem Ende des Krieges hat unser Volk etwas gebraucht, das uns Halt gibt und das uns nach allem, was uns widerfahren ist, einen Sinn vermittelt.\n\nIch sah Calia auf den Thronsaal zugehen. Dieser Ort birgt viele Erinnerungen für sie. Viele Geister.\n\nWir sollten nach ihr sehen.", sourceObjective = "Sprecht mit Calia im Thronsaal von Lordaeron.", completion = "Ich danke Euch, {name}. Ihr habt mir sehr geholfen.\n\nIch weiß, dass die Verlassenen von hier aus ihre Identität wiederherstellen und festigen können. Nicht nur als ehemalige Bewohner von Lordaeron, sondern als eigenes Volk. Ein Volk, dem ich mit Stolz angehöre.", sourceObjectiveStatus = "unverified-source-field" }
quests[65789] = { id = 65789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Flüsse schlafen", description = "Im Sumpfholzmoor lassen sich wichtige Reagenzien finden, die oft zur Kommunikation mit den Ahnen verwendet werden. Unglücklicherweise durchstreift der Schlickflossenstamm diese Gegend und hindert uns daran, sie einzusammeln.\n\nIch würde es sehr zu schätzen wissen, wenn Ihr ein paar der Gewächse im Moor und einige Ressourcen der Schlickflossen auftreiben könntet.", sourceObjective = "Sammelt Reagenzien im Sumpfholzmoor.", progress = "Habt Ihr alles gefunden?", completion = "Ich danke Euch. Wir werden dies sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65791] = { id = 65791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensbinderin im Einsatz", description = "Bald werden die Lebensbecken wieder gefüllt sein.\n\nDanke für Eure Hilfe dabei, {name}. Es bedeutet mehr, als ich je in Worte fassen könnte.\n\nGeht und sucht die Lebensbinderin beim Schwurstein auf. Sagt ihr, dass wir bereit für die Eier sind.", sourceObjective = "Trefft Alexstrasza beim Rubinschwurstein.", completion = "Die Zukunft aller Schwärme ist nun gesichert.", sourceObjectiveStatus = "unverified-source-field" }
quests[65792] = { id = 65792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zähne um Zahn", description = "Toliqui hat behauptet, neulich einen Felszahn ohne Hilfe erlegt zu haben. Da unsere Seelen miteinander verbunden sind, möchte ich ihr nicht vorwerfen, gelogen zu haben. Stattdessen...\n\nIch will ihr und allen anderen beweisen, dass ich die bessere Hälfte unserer Seele bin! Die nächste Felszahnaufgabe wartet im Nordosten auf uns. Trefft mich dort!", sourceObjective = "Tötet 10 Felszähne mit Toluijin.", progress = "Ich kann nicht länger in Toliquis Schatten stehen.", completion = "Der Klan wird noch in Wochen darüber reden!", sourceObjectiveStatus = "unverified-source-field" }
quests[65793] = { id = 65793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eieskorte", description = "Nachdem der Schwurstein wieder ermächtigt wurde, müssen wir nun die Zukunft unserer Art zu den Lebensbecken bringen. Es ist das Recht eines jeden wahren Drachenschwarms, seine Eier in seinen eigenen Gewässern pflegen zu lassen.\n\nLeider werden unsere Feinde den Himmel beobachten, nachdem wir uns offenbart haben. Wir werden die letzte Etappe der Reise zu Fuß zurücklegen, um ihren Blicken zu entgehen.\n\nTrefft mich in der Nähe des Obsidianbollwerks, {class}. Als Champion der Lebensbinderin möchte ich Euch einladen, mich zu begleiten.", sourceObjective = "Eskortiert die Eier zu den Lebensbecken.", completion = "Ihr habt mir vorbildlich gedient, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[65794] = { id = 65794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht der Pflege", description = "Ich danke Euch, {class}. Und mein Beileid dafür, dass Ihr so lange mit den beiden zu tun hattet.\n\nDer rote Drachenschwarm hat die Aufgabe, alle Drachen zu beschützen und zu pflegen, auch jene, derer wir vielleicht manchmal überdrüssig sind.\n\nMit der Rückkehr der Eier des schwarzen Drachenschwarms ist die Drachengemeinschaft so geeint wie seit tausenden von Jahren nicht mehr. Ich glaube, das ist es, was unseren Rubinschwurstein wiederherstellen wird.\n\nSprecht mich an, wenn Ihr bereit seid, die Eier zum Obsidianlebensbecken zu bringen.", sourceObjective = "Seht zu, wie die Schwarzdracheneier erneut in den Lebensbecken ihren Platz finden.", completion = "Die Lebensbecken sind wieder gefüllt, was zu großen Teilen auch Euer Verdienst ist.\n\nDa unsere Aufgabe erfüllt ist, erstrahlen die Schwursteine wieder als Symbole unserer Bestimmung.", sourceObjectiveStatus = "unverified-source-field" }
quests[65795] = { id = 65795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in die Steppe", description = "Der grüne Drachenschwarm braucht jetzt Eure Hilfe. Die Tochter meiner Schwester und ihr Schwarm sind in den Smaragdgrünen Traum eingedrungen, um ihren eigenen Schwurstein zu stärken. Aber wir haben nichts mehr von ihnen gehört, seit ihr Schlummer begann.\n\nSucht die Zentauren auf, die über die Ebenen von Ohn'ahra herrschen. Ihr könntet ihre Verbindung zum Land und seinen Geistern gut brauchen, wenn ihr die Grünen wecken wollt.\n\nSie sind ein stolzes und sehr territoriales Volk, das sehr empfindlich auf vermeintliche Beleidigungen reagiert. Sprecht mit unserem Botschafter. Er wird Euch vorbereiten.", sourceObjective = "Trefft Botschafter Taurasza im Außenposten der Rubinschuppen.", completion = "Wir beide haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65796] = { id = 65796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die beste Verteidigung...", description = "Unser nächster Pfad führt uns durch das Territorium der Nokhud. In der Vergangenheit herrschte ein vorläufiger Frieden zwischen unseren Klans, aber die Zeiten haben sich geändert.\n\nWenn wir nicht zuerst handeln, machen wir uns angreifbar. Meine Späher haben berichtet, dass eine ihrer Kriegsanführerinnen nahe Drachentreff gesichtet wurde. Greift sie zuerst an, lasst ihr keine Zeit, ihre Truppen zu sammeln, um uns unterwegs überfallen.", sourceObjective = "Tötet Sirena die Zahnbrecherin.", completion = "Danke, das beruhigt mich und hilft mir, mich auf unsere Reise vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65798] = { id = 65798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine opportunistische Herangehensweise", description = "Die Shikaar haben gegen die Nokhud im Norden eine Angriffslinie gebildet. Es gefällt mir eigentlich nicht, uns zum Plündern herabzulassen, doch es ist leider ein notwendiges Übel, um unsere Vorräte aufzufüllen. Trotzt dem Schlachtfeld und kehrt mit Waffen zurück. Ich werde Eure Mühen entlohnen.\n\nWenn Ihr ebenjene Mühen auf die Seite der Nokhud konzentriert, werden die Ahnen mich hoffentlich nicht ganz so sehr verurteilen.", sourceObjective = "Sammelt Waffen und erschlagt Nokhud-Kämpfer beim Vorstoß der Nokhud.", progress = "Waffen werden am nützlichsten sein... Es tut mir leid, Euch darum zu bitte.", completion = "Ahnen, vergebt mir. Wenn ich nur stärker wäre, müssten wir nicht auf solche fragwürdige Methoden zurückgreifen, um Ressourcen zu sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[65801] = { id = 65801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorstellungsrunde", description = "<Während Sansok Khan in Gebärden spricht, übersetzt Okir für sie.>\n\nEs ist Generationen her, seit ein Fremdling wie Ihr Fuß auf unser Land setzte. Angesichts der Primalisten, die unser Land heimsuchen und ihre verbotene Magie ausüben, ist mein Volk verständlicherweise misstrauisch.\n\nWenn Ihr mit uns reisen wollt, müsst Ihr Euch mit meinem Klan bekanntmachen. Stellt Euch den Mitgliedern vor.", sourceObjective = "Stellt Euch den Mitgliedern von Klan Shikaar vor.", progress = "Gut. Die Khan hat Arbeit für Euch gefunden.", completion = "Der Rest unseres anwesenden Klans ist bereits nach Maruukai gereist, um unser Lager vorzubereiten. Die Karawane von diesem Außenposten wird die letzte sein, die ankommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65802] = { id = 65802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für die Reise", description = "<Während Sansok Khan in Gebärden spricht, übersetzt Okir für sie.>\n\nWährend Ihr mit uns reist, müsst Ihr Euren Soll erbringen. Wilde Gorlocs haben kürzlich unsere medizinischen Vorräte geplündert, und wir benötigen dringend Nachschub. Sammelt die orangen Blüten, die Ihr im Umkreis des Außenpostens findet, damit wir mehr Heilumschläge herstellen können.\n\nUm den Außenposten herum liegen auch Vorräte, die zur Karawane gebracht werden müssen. Sammelt sie bitte mit auf.\n\nWenn Ihr alles beisammen habt, bringt es zu Tomul.", sourceObjective = "Sammelt 5 Lagervorräte in der Gegend des Baumschrittaußenpostens und 4 Wildblütenkapseln im nahen Wald.", progress = "Stört mich nicht, solange Ihr nicht die Vorräte für die Karawane habt.", completion = "<Späherin Tomul sieht zu den gesammelten Vorräten hinüber.>\n\nAlles scheint vorbereitet zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[65803] = { id = 65803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Stadt", description = "Der Khural ist eine Zeit, wo die Klans sich besprechen und Geschichten austauschen. Es gibt viele Zentaurenklans auf den Ebenen, aber wir alle sind Maruuk.\n\nDie Karawane ist reisefertig. Da Maruukai etwas weiter weg ist, werden wir Halt machen müssen.\n\nWenn Ihr bereit zum Aufbruch seid, findet Ihr mich am Wagen. Lasst uns nicht warten.", sourceObjective = "Reist mit der Shikaarkarawane zur Steppe des Wanderers.", completion = "Atmet kurz durch, Zweifüßer.", sourceObjectiveStatus = "unverified-source-field" }
quests[65804] = { id = 65804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Speisen und Rivalität", description = "Die Maruuk reisen aus allen Teilen der Ebenen an, um am Khural teilzunehmen. Die Zusammenkunft erstreckt sich über mehrere Tage.\n\nSo viele Zentauren satt zu bekommen, ist kein leichtes Unterfangen. Die Jäger der Shikaar liefern das Fleisch für alle gemeinsamen Mahlzeiten. Nach unserer Tradition jagen wir auf dem Weg nach Maruukai.\n\nAuch Ihr müsst Euren Beitrag leisten.", sourceObjective = "Erbeutet 30 Teile frisches Wildfleisch von den Tieren in der Steppe des Wanderers.", progress = "Unsere jüngsten Jäger sind leidenschaftlich und entschlossen. Passt auf, dass sie Euch nicht vorführen.", completion = "Ihr jagt so außergewöhnlich, wie Ihr kämpft. Ich hoffe, Aru und Belika haben sich Eure Technik eingeprägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65805] = { id = 65805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbindung zu Ohn'ahra", description = "Der Wind zeigt sich hier ruhelos, {name}. Ohn'ahra ruft. Und ich muss ihrem Ruf folgen.\n\nIch brauche Reagenzien für mein Ritual: Schilf vom Flussufer, Federn von den Schwänzen der Stockenten und das Herz eines Salamanthers. Sammelt diese Materialien am Fluss, damit ich ihrer Stimme folgen kann.", sourceObjective = "Sammelt 4 Teile Flussschilf, 8 Vogelschwanzfedern und ein Salamantherherz am Flussufer.", progress = "Ohn'ahras Lied vergeht. Wir müssen schnell handeln.", completion = "Ausgezeichnet. Ich werde diese Materialien nutzen, um ihr Lied zu interpretieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65806] = { id = 65806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maruukai", description = "<Während Sansok Khan in Gebärden spricht, formuliert Okir die Worte.>\n\nMaruukai liegt an einem Berghang in der Nähe dieses Waldes. Unsere Reise ist fast zu Ende.\n\nDer Khural ist eine Zeit des Friedens bei den Maruuk, aber Ohn Seshtengs Omen ist beunruhigend. Wir müssen auf der Hut sein.", sourceObjective = "Reist nach Maruukai.", completion = "Willkommen in Maruukai.", sourceObjectiveStatus = "unverified-source-field" }
quests[65832] = { id = 65832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergenfrostschutz", sourceObjective = "Findet 6 Fläschchen Zwergenfrostschutz.", progress = "Ich spür meine Zehen schon nicht mehr!", completion = "Magni sei Dank! Das wird mein Blut vorm Einfrieren bewahren, bis das Eis aufgetaut ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[65833] = { id = 65833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmischung der Primalisten", description = "Die Primalisten erfüllen die Spinnen mit Elementareis, um sie als Kanonenfutter gegen die Verteidigung der Drachen im Gebirge einzusetzen und sie zu überrennen. Das dürfen wir nicht zulassen.\n\nDie drei Frostbeulen haben das Kommando. Schaltet sie aus und bringt mir ihre Runensteine, mit denen sie die Urmagie fokussieren. Damit sollten wir den Magiestrom unterbrechen können.", sourceObjective = "Erbeutet die drei Frostruferrunensteine.", progress = "Habt Ihr alle drei?", completion = "Geschieht ihnen recht.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[65834] = { id = 65834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Königin", description = "Und fertig ist der Lack! Mit ein bisschen Wissen, gesundem Raten und ein paar neugemeißelten Runen haben wir jetzt einen magischen... Enterfüller? Entfüller? Ausfüller?\n\nEgal! Bin ziemlich sicher, dass er irgendwas Unschönes mit der Königin anstellen wird. Und um die Bedrohung loszuwerden, müssen wir sie loswerden. Die Kleinen zu zerquetschen, verzögert alles nur, wir müssen dies im Keim ersticken.", sourceObjective = "Tötet die Schaudernetzkönigin.", completion = "Ja, das sollte ihren Plan vereiteln.\n\nJetzt noch... ein kleines... bisschen mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[65836] = { id = 65836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine stürmische Demonstration", description = "<Watu steht ohne Probleme auf, als ob seine Verletzung verschwunden wäre.>\n\nI-i-ich... habe mir den Splitter reingerammt. Nichts schmerzt mehr. Ich fühle mich gut. Blendend. Gewaltig.\n\nOlekk ist immer noch nicht zurück. Etwas stimmt nicht. Er hätte niemals ohne mich gehen sollen!", sourceObjective = "Formiert Euch mit Watu im Weisenkronenpinienwald neu.", completion = "Nein!", sourceObjectiveStatus = "unverified-source-field" }
quests[65837] = { id = 65837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probleme im Nadelholz", sourceObjective = "Sprecht mit Wächter Olekk im Nadelholzposten auf den Ebenen von Ohn'ahra.", completion = "Tirren? Er galoppiert also immer noch herum?\n\nDanke, dass Ihr gekommen seid. Wir können alle Hilfe brauchen, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[65838] = { id = 65838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brackenfelle brechen", description = "Wenn die Gnolle Verfallmagie entdeckt haben, sind die Leylinien und das Land selbst in großer Gefahr.\n\nMeine Spiegelbilder sind zu ausgedünnt, um elementaren Störungen dieses Ausmaßes zu widerstehen. Bitte betretet den Wald und untersucht den Verfall.\n\nIch werde mit unseren neuen Freunden von den Tuskarr zusammenarbeiten und einen Ort suchen, an dem ich mein Spiegelbild aufrechterhalten kann. Ich treffe Euch anschließend tiefer im Wald.\n\nWir müssen dem ein Ende setzen!", sourceObjective = "Untersucht die Brackenfellrandgebiete.", progress = "Könnt Ihr die magischen Störungen um uns herum spüren?", completion = "Ihr solltet Euren Mund bedecken. Diesen Verfall möchtet Ihr nicht einatmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65840] = { id = 65840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So wie der alte Boss", description = "Die Weltenbrecherdrachkin sind ein vertrauensvoller Haufen. Über die Jahre hinweg sind wir vielen Anführern gefolgt, in der Hoffnung, dass sie uns zur Stunde des Zwielichts führen und die Rückkehr von Todesschwinge einläuten.\n\nAber Todesschwinge ist nicht zurückgekehrt und die Stunde des Zwielichts ist nie eingetreten.\n\nEs ist Zeit für einen neuen Anführer. Ihr könnt helfen, diesen Wechsel zu vollziehen.", sourceObjective = "Schaltet Doventhal den Auserwählten aus.", completion = "Das habt Ihr gut gemacht. Jetzt gibt es reichlich Platz für den Aufstieg eines neuen Anführers, der die Weltenbrecher hoffentlich in eine bessere Zukunft führen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[65841] = { id = 65841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbreitung verhindern" }
quests[65842] = { id = 65842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwaffnendes Verhalten", description = "Ich habe wenig für die Weltenbrecherdrachkin übrig. Sie hängen einem fehlgeleiteten Glauben an, dass Todesschwinge zurückkehren wird, und helfen uns nicht mit dem Obsidianthron.\n\nWaffenmeisterin Vordak, die dem Schwarzen Prinzen einst die Treue schwor, hat etliche hier in der Zitadelle hergestellten Waffen gestohlen und den Weltenbrechern übergeben. Diesen Diebstahl werde ich nicht dulden. Diesen Verrat auch nicht.\n\nGeht zur Schwelenden Spitze und holt die Waffen zurück... wenn nötig mit Gewalt.", sourceObjective = "Schaltet Waffenmeisterin Vordak aus und sammelt 15 Weltenbrecherwaffen.", progress = "Habt Ihr die Waffen beschafft?", completion = "Gut gemacht. Die Waffen sind wieder dort, wo sie hingehören.\n\nIch bin sicher, dass das nicht der letzte Konflikt sein wird, der sich zwischen uns und den Weltenbrechern auftut. Niemand, der verrückt genug ist, an Todesschwinges Rückkehr zu glauben, ist für vernünftige Argumente zugänglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[65844] = { id = 65844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fäulnis herausschneiden", description = "Dieser Verfall muss die Gehirne der Gnolle wie ihre Körper zerfressen haben!\n\nWie zerstörerisch sie auch sein mögen: Gnolle sind in diesem Land heimisch... genau wie wir.\n\nWir beobachteten jedoch bereits, wie sie den Verfall bis zu den Riesenbaumhügeln ausbreiteten. Wenn das so weitergeht, werden sie noch das Gebirge infizieren und sich selbst vernichten.\n\nDas dürfen wir nicht zulassen. Es ist bedauerlich, aber... wir müssen ihnen ein Ende setzen.", sourceObjective = "Tötet 5 verfaulende Treants und 10 Fäulniswerfer von Brackenfell.", completion = "Gnolle sind schon faszinierende Wesen! Dabei sind sie nicht inhärent böse, nur wild. Und sehr, sehr dumm.\n\nEs ist bedauerlich, dass wir sie ausrotten müssen, aber mit dem Verfall ist niemandem gedient. Und wir dürfen nicht zulassen, dass sie unserer Familie etwas zuleide tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[65845] = { id = 65845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos der Gefallenen", description = "Hier liegen Tuskarr! Die Leichen meiner Freunde, meines Volkes... meiner Familie. Sie sind vor nicht einer Woche erst zur Jagd aufgebrochen.\n\nSie sind schon zu verwest, um sie zu bergen.\n\nIhre Geister sind noch hier. Ihr Zorn, ihre Reue fesselt sie an diesen Ort. Kaqiata, Litokk, Tuyuki...\n\nIch bitte Euch, {name}, nehmt mein Totem und stellt es in der Nähe ihrer Leichen auf. Ich werde ihre Geister anrufen... auf dass sie endlich Frieden finden.", sourceObjective = "Platziert Brenas Totem in der Nähe von 5 Leichen der Tuskarr, um Kontakt zu ihren Geistern aufzunehmen.", completion = "Also haben sie alle beschlossen, ihre Macht meinem Totem zu leihen?\n\n<Brena schließt sorgenvoll ihre Augen.>\n\nHabt Dank, meine Freunde. Wir werden die Stärke Eurer Geister gut einsetzen. Die Gnolle werden Iskaara nicht erreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65846] = { id = 65846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liegengelassenes Ley", description = "Die Leylinie muss hier sein. Ich spüre sie!\n\nAber zunächst müssen wir die Gnolle aufhalten. Dieses Urtum ist vermutlich ihre mächtigste Waffe.\n\nEs befinden sich einige Leykristalle hier, die die Gnolle gesammelt haben. Zum Glück scheinen sie die Macht, die den Kristallen innewohnt, nicht zu verstehen.\n\nBringt mir so viele, wie Ihr könnt. Sie werden mein Spiegelbild stärken und mir helfen, etwas Nützliches aus den Archiven zu beschwören, um das Monster auszuschalten.", sourceObjective = "Sammelt 7 Leykristalle in den Brackenfellrandgebieten.", progress = "Es tut mir leid, dass ich in dieser Gestalt nicht mehr behilflich sein kann. Ich spüre, wie der Verfall von der Stärke meines Abbilds zehrt.\n\nIch hoffe, sobald wir die Leyhöhle erreichen... oder Glimmerhöhle, wie die Tuskarr sie nennen... kann ich mich vollständig hierherteleportieren.", completion = "Was haben sie bloß damit angestellt? Haben sie die als Rückenkratzer missbraucht?!\n\n<Kalecgos kneift sich in die Nase.>\n\n...Nun, wir sollten wohl dankbar sein, dass sie ihr wahres Potenzial nicht erkannt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[65847] = { id = 65847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuausrichtung", description = "Nun zu dieser Leylinie. Meine Befürchtungen scheinen sich zu bestätigen... der Verfall hat sich in der Linie ausgebreitet.\n\nWir müssen den Verfall entfernen und den Heilungsprozess beschleunigen, aber ich kann mit meinem Spiegelbild alleine nicht genug Energie hineinkanalisieren.\n\nKonzentriert Euch auf diesen Leykristall hier. Meine Verbindung zu Euch wird mir dabei helfen, mich physikalisch hierherzuteleportieren. Dann werde ich stark genug sein.", sourceObjective = "Konzentriert Euch auf den Leykristall und zerstört dann 3 Verfallansteckungen.", progress = "Der Verfall ist hier zwar etwas zurückgegangen, aber er ist noch immer stark genug, um sicheres Teleportieren zu gefährden.", completion = "Wir haben es geschafft. Großartige Arbeit, {name}. Atmet endlich wieder frische Luft!\n\nDa diese Leylinie wiederhergestellt ist und Khadgar an derjenigen im Turm die letzten Vorbereitungen trifft, sollte der Schwurstein bereit sein, beansprucht zu werden. Ich muss bald zu den Azurarchiven zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65848] = { id = 65848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Folianten", description = "Wir müssen diesen Baum aufhalten! Dank der Leykristalle kann ich endlich mithelfen.\n\nSprecht mich an, wenn Ihr bereit seid. Ich werde ein Portal zu den Azurarchiven öffnen und versuchen, etwas Nützliches hervorzubringen.\n\nHaltet Abstand, es könnte ziemlich instabil sein.", sourceObjective = "Sprecht mit Kalecgos, damit er das Portal öffnet, und nutzt, was er beschwört, um die Verderber von Brackenfell auszuschalten und schließlich das kranke Urtum zu vernichten.", progress = "Das dürfte interessant werden!", completion = "Das habt Ihr gut gemacht, danke.\n\nDer Baum war wahrscheinlich nicht ihre einzige Verfallsquelle, aber zumindest die gefährlichste für die Tuskarr und diese Leylinie. Nachdem sie nicht mehr da ist, dürfte sich die Gegend wieder erholen. Das wird zwar dauern, aber es wird gelingen.\n\nIch bin froh, dass wir den Geistern dieser Tuskarr Frieden schenken konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65849] = { id = 65849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Iskaara", description = "Ich danke Euch, {name}. Dank Euch ist meine Familie in Sicherheit.\n\nJetzt können wir endlich nach Iskaara zurückkehren und den alten Ponoliak der See übergeben. Er war mein Mentor und ein guter Häuptling.\n\nBitte, schließt Euch uns an! Jeder kann sich an der Feier des Kreislaufs des Meeres beteiligen.", sourceObjective = "Trefft Brena in Iskaara.", completion = "Ich bin so froh, dass Ihr hier seid.\n\nDoch ich muss Euch bitten, geduldig zu sein. Es muss noch etliches für die Zeremonie vorbereitet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[65850] = { id = 65850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreislauf des Meeres", description = "Danke, {name}. Ich habe von unseren neuen Freunden alles Nötige erfahren.\n\nDie Bestattungszeremonie für ihren ehemaligen Häuptling beginnt bald. Angesichts ihrer Güte und Gastfreundschaft uns gegenüber wäre es nur angemessen, daran teilzunehmen, bevor wir in die Archive zurückkehren.\n\nRedet mit Brena und lasst sie wissen, dass wir jederzeit bereit sind.", sourceObjective = "Sprecht mit Brena, um an der Beerdigungszeremonie teilzunehmen.", progress = "Es ist gut, es von Zeit zu Zeit etwas langsamer angehen zu lassen. Und interessant, die Traditionen der Tuskarr zu sehen.\n\nEs ist lange her, seit der blaue Drachenschwarm Traditionen wie diese gehabt hat.", completion = "<Kalecgos wirkt abwesend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65852] = { id = 65852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direkt zur Spitze", description = "Anscheinend entzieht etwas an der Spitze des Turms die arkanen Energien.\n\nNun, da Ihr die Energien hier unten stabilisiert habt, solltet Ihr in der Lage sein, die arkanen Magien der Gegend zu \"reiten\".\n\nSucht in Eurer Tasche nach etwas, das sich \"Arkaner Trittstein\" nennt. Setzt ihn ein, damit wir uns oben treffen können.", sourceObjective = "Sucht in der Tasche nützlicher Waren nach dem arkanen Trittstein und nutzt ihn an einem arkanen Fokuspunkt, um die Spitze der Azurarchive zu erreichen.", progress = "Von hier aus geht es weit nach unten. Seid vorsichtig.", completion = "Hier oben ist es schlimmer, als ich befürchtet hatte!", sourceObjectiveStatus = "unverified-source-field" }
quests[65854] = { id = 65854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneute Beanspruchung des Schwursteins", description = "Hervorragende Arbeit. Offenbar ist es uns gelungen, die Leylinien in den Azurarchiven zu reparieren.\n\nFrüher, als der blaue Drachenschwarm vereint war, hätte ich meinen Brüdern und Schwestern gesagt, nie an der Stärke der Sterblichen zu zweifeln.\n\nTrefft mich am Schwurstein südlich von hier. Ich werde ihn beanspruchen und mich dann auf den Weg nach Thaldraszus begeben.", sourceObjective = "Seht zu, wie Kalecgos den Azurschwurstein neu beansprucht.", completion = "Es ist gut, zurück zu sein... oder reaktiviert zu sein, besser gesagt.\n\nEs gibt viel zu tun und ich helfe gern, wo ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[65855] = { id = 65855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für das Azurblaue Gebirge", description = "Die Energie des Schwursteins kann nicht wieder beansprucht werden, bis die Leylinien innerhalb des Azurblauen Gebirges repariert wurden.\n\nEinige von ihnen können womöglich nur mithilfe von Kalecgos' Fähigkeiten erreicht werden... aber Ihr könnt dennoch helfen.\n\nFindet heraus, ob die Tuskarr überlebt haben, und sucht sie in dem Fall auf. Sie haben zu meiner Zeit hier gelebt und besitzen umfangreiches Wissen über diese Gegend.\n\nSprecht mit einem unserer arkanen Helfer, um zu Euren Verbündeten zurückzukehren.", sourceObjective = "Kehrt zu Noriko der Allerinnernden im Lager Antonidas zurück.", completion = "Die Tuskarr? Es gibt einige Händler und Reisende der Tuskarr, die hier vorbeikommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65864] = { id = 65864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karawane erwischen", description = "Ihr solltet Brena hinterher. Ihre Karawane ist gerade einmal vor ein paar Stunden hier durchgekommen.\n\nSie haben die wertvollsten Besitztümer unseres verstorbenen Häuptlings für ein Begräbnis zu seinen Ehren gesammelt.\n\nDa die Karawane schwer beladen war, dürfte sie noch nicht weit gekommen sein.", sourceObjective = "Holt Brena in der Nähe der Riesenbaumhügel ein.", progress = "Ich bin bei Euch, Hanu.", completion = "Die Gnolle haben gnadenlos angegriffen.\n\nSie haben schnell und heftig zugeschlagen und alles mitgenommen, was nicht niet- und nagelfest war.", sourceObjectiveStatus = "unverified-source-field" }
quests[65865] = { id = 65865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben uns festgesetzt!", description = "Diese Scharfschützen der Gnolle sind gnadenlos... und überraschend zielsicher.\n\nSolange sie ihre Waffen auf uns gerichtet haben, können wir nicht einmal daran denken, in die Riesenbaumhügel aufzubrechen.\n\nDünnt ihre Reihen aus und zeigt ihnen, dass wir keine lebenden Zielscheiben sind!", sourceObjective = "Tötet Gnollscharfschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65866] = { id = 65866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen auslösen", description = "Die Hügel vor uns sind mit Klingenkieferfallen gespickt.\n\nAber wenn Ihr aufmerksam seid, solltet Ihr sie aufspüren können. Löst sie mit diesem alten Trick der Tuskarr vorsichtig aus: Nehmt einem langen Stock. Natürlich könntet Ihr das auch tun, indem Ihr in sie hineintretet, aber das würde ich nicht empfehlen.\n\nSucht Hanu auf, sobald Ihr genügend von ihnen entfernt habt. Die Älteste Poa und ich werden nachkommen, sobald wir können.", sourceObjective = "Löst 5 Klingenkieferfallen aus.", completion = "Gut gemacht. Damit ist der Weg hierher für Brena sicherer.", sourceObjectiveStatus = "unverified-source-field" }
quests[65867] = { id = 65867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heulen in den Riesenbaumhügeln", description = "Die Gnolle, die unsere Karawane angegriffen haben, wurden von drei Leutnants angeführt.\n\nDurgun wurde von einem Dutzend Hyänen begleitet.\n\nKerwal lachte jedes Mal wie wahnsinnig, wenn wir ihn verfolgen wollten und in eine seiner Stahlfallen getappt sind.\n\nBakra hat uns erbarmungslos verspottet.\n\nWenn wir auch nur darauf hoffen wollen, das wiederzuerlangen, was gestohlen wurde, müssen sie sterben.", sourceObjective = "Tötet Durgun, Kerwal und Bakra.", progress = "<Hanu starrt Euch unverwandt an.>", completion = "Gut, Ihr habt getan, was ich nicht konnte.\n\nAber es gibt noch einen weiteren Gnoll, der die Schattenpfoten anführt... und er ist furchteinflößender als die drei, denen Ihr begegnet seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[65868] = { id = 65868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts zum Knabbern", description = "Ich habe eine von Ponoliaks Bestattungsgaben gefunden, von diesen Schattenpfotengnollen verschandelt und dann weggeworfen... Sie war voller Bissspuren.\n\nDiese Gabe, zusammen mit anderen, wird für die Beerdigungszeremonie unseres jüngst verstorbenen Häuptlings von Iskaara benötigt.\n\nEs ist eine Schande, etwas so Heiliges als Kauspielzeug zu verwenden. Bitte haltet die Augen nach weiteren Bestattungsgaben offen.", sourceObjective = "Holt 8 Bestattungsgaben zurück.", progress = "<Hanu beugt sich vor und linst erwartungsvoll in Euren Rucksack.>", completion = "<Hanu rümpft die Nase.>\n\nUgh... triefend vor Sabber.\n\nDas muss für das Denkmal des Häuptlings reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65869] = { id = 65869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch ein Hinterhalt", description = "Eine Tragödie. Und möglicherweise nur die erste von vielen.\n\nFindet heraus, was Akiun weiß, und untersucht dann alle, die bei dem Angriff ums Leben gekommen sind.\n\nIch habe da so meine Vermutungen, was hier geschehen ist. Finden wir heraus, ob die Spuren meine Theorie bestätigen.\n\nIch werde versuchen, meinen aufgewühlten Freund zu beruhigen.", sourceObjective = "Sprecht mit Akiun und untersucht 4 Leichen in der Nähe.", completion = "Das ist wahrlich eine Tragödie... aber zumindest haben wir eine Spur.\n\nWir kommen der Quelle dieses Verfalls näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[65870] = { id = 65870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte!", description = "In den Riesenbaumhügeln war keine Spur von unserer gestohlenen Jagdausrüstung. Sie muss in dieser Höhle sein.\n\nHaltet die Augen nach Ausrüstungsbehältern offen und seid auf alles gefasst.\n\nIch würde nicht davon ausgehen, dass die Gnolle die Behälter unbewacht zurückgelassen haben.", sourceObjective = "Bergt die Behälter mit Jagdausrüstung.", progress = "Ich will Iskaara nicht hungern sehen...", completion = "<Die Älteste Poa betrachtet die von Euch geborgenen Vorräte anerkennend.>\n\nDie Tuskarr von Iskaara gehen wieder auf die Jagd.", sourceObjectiveStatus = "unverified-source-field" }
quests[65871] = { id = 65871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Weg an den Gnollen vorbei", description = "Ich bin der Fährte der gefangenen Tuskarr gefolgt. Sie und mein Mann Norukk sind in dieser Höhle.\n\nNorukk gibt oft nicht genügend auf sich selbst acht, deshalb tue ich das normalerweise für ihn. Aber ein wenig Hilfe werde ich nicht ablehnen.\n\nBitte rettet sie!", sourceObjective = "Rettet Norukk und 3 weitere gefangene Tuskarr.", progress = "Wir dürfen unsere Brüder und Schwestern nicht zurücklassen!", completion = "<Hanu verzieht ihr Gesicht und wirft Norukk ein freundliches Stoßzahngrinsen zu.>\n\nIch bin sehr erleichtert, dass Norukk es lebend rausgeschafft hat. Um die, die wir verloren haben, werden wir trauern, wenn wir wieder in Iskaara sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[65872] = { id = 65872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse Gnolle mit bösen Absichten", description = "Ich wittere etwas Seltsames in der Luft. Hier stimmt etwas nicht...\n\nHanu hat die Gnolle in dieser Höhle als eigenartig beschrieben... und krank. Wir sollten mehr über den Ursprung von alldem herausfinden.\n\nAber werdet nicht übermütig. So kränklich sie auch aussehen, sie dürften hochgradig hinterhältig und gefährlich sein.", sourceObjective = "Tötet 16 Schattenpfotengnolle in Kargtatzes Höhle.", completion = "Wir haben noch nie gesehen, wie Fäulnis auf solche Art und Weise Form annimmt.\n\nDas ist bedenklich.", sourceObjectiveStatus = "unverified-source-field" }
quests[65873] = { id = 65873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführer der Schattenpfotenbande", description = "Kargtatze ist der wahre Anführer der Gnolle in diesem Teil des Waldes. Wir hatten in der Vergangenheit bereits... unangenehme Begegnungen mit ihm.\n\nAber diesmal war etwas anders. Er hatte ein seltsames Totem bei sich, das seine gesamte Essenz zu verzerren.\n\nWir müssen Kargtatze aufhalten und dieses Totem in unseren Besitz bringen. Ich befürchte, die Gnolle spielen mit etwas, das dunkler ist, als wir es uns vorstellen können.", sourceObjective = "Tötet Kargtatze und nehmt sein Totem an Euch.", progress = "Habt Ihr Kargtatzes Totem dabei?", completion = "<Brena weicht angewidert zurück, als sie das Totem annimmt.>\n\nKargtatze war schon immer brutal, aber auch ein Feigling. Er und seine Bande haben uns nie angegriffen, wenn wir ihnen zahlenmäßig überlegen waren.\n\nEtwas hat sich verändert... und dieses Totem ist der Grund.", sourceObjectiveStatus = "unverified-source-field" }
quests[65874] = { id = 65874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verdorbene Offenbarung", description = "Hm...\n\n<Brel starrt das seltsame Totem unverwandt an und dreht und wendet es in ihren wuchtigen Händen.>\n\nWir müssen die Barthaare zusammenstecken und herausfinden, was es damit auf sich hat.", sourceObjective = "Sprecht mit Hanu, der Ältesten Poa und Norukk.", sourceObjectiveStatus = "unverified-source-field" }
quests[65875] = { id = 65875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Drache macht blau", description = "Ein ganzes Leben in der Scherbenwelt... ständige Kämpfe. So wenig Zeit zum Entspannen.\n\nHin und wieder braucht ein Drache einen Tag am Meer, mit einem richtig kalten Getränk in seinen Klauen.\n\nHey, vielleicht könnt Ihr mir dabei helfen, mich zu entspannen! Tut mir einen Gefallen und schaut, ob Ihr einige dieser Getränke findet, um unseren Vorrat aufzustocken.", sourceObjective = "Findet die Getränke für Vazallia.", progress = "Habt Ihr schon meine Getränke? Nein? Das ist wirklich schade.", completion = "Ja! Zeit, sich zurückzulehnen und zu entspannen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65886] = { id = 65886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Rhonins Schild", description = "Raszageth und die Primalisten starten einen Großangriff auf Vakthros. Wir dürfen nicht zulassen, dass sie Erfolg haben!\n\nKhadgar und ich werden vorgehen und die Situation aus dem Himmel unter Kontrolle bringen.\n\nIn der Zwischenzeit müsst Ihr Euch zu Rhonins Schild aufmachen, einem der letzten Lager der Kirin Tor in dieser Gegend.\n\nIhr seid schneller, wenn Ihr von der Spitze des Archivs mit Eurem Drachen losfliegt.\n\nStellt sicher, dass es den Kirin Tor gut geht und begebt Euch dann nach Vakthros.\n\nWir zählen auf Eure Bodenunterstützung.", sourceObjective = "Trefft Euch mit Drok Schriftstecher im Turmausguck.", completion = "Kalecgos und Khadgar sind gerade in Richtung der Berge aufgebrochen. Wir halten die Stellung gegen die Primalisten, aber zusätzliche Hilfe können wir immer brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65887] = { id = 65887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Bergen", description = "Was für ein Anblick da oben, wie Khadgar und Kalecgos die Primalisten am Himmel bekämpfen!\n\nSie haben mehrere Abbilder von sich beschworen, um Euch durch das gigantische Loch zu helfen, das die Primalisten erschaffen haben.\n\nZwei davon befinden sich gerade am Fuß der Berge.\n\nWenn die Dinge sich zum Schlechten wenden... nun, dann werde ich den Rest von uns im Azurblauen Gebirge informieren.", sourceObjective = "Trefft Khadgars und Kalecgos' Abbilder am Fuß der Bergkette von Vakthros.", completion = "Das ist schlimmer, als ich es hätte erwarten können. Wir haben keine Zeit zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65890] = { id = 65890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Nelthazan", description = "Die Drachenschuppenexpedition benötigt Eure Unterstützung.\n\nEin Himmelsschreiber wurde zum Sammeln von Informationen in die Ruinen geschickt. Sie sollten unbewohnt sein, aber ich kann ihn bis hier schreien hören.\n\nEr muss in einer brenzligen Situation sein, wenn er bis hierher zu hören ist.\n\nAuf dieser Expedition kümmern wir uns um einander. Sogar um die Unerträglichen. Sucht nach ihm und schützt ihn vor was auch immer er dort gefunden hat.", sourceObjective = "Trefft den Himmelsschreiber Adenedal bei den Ruinen von Nelthazan.", completion = "Natürlich schreie ich! Das Buch will nicht zuhören. Was sollte ich sonst tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[65891] = { id = 65891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mittel zum Zweck", description = "Gut. Ich habe mir gerade überlegt, dass ich <einen Abenteurer/eine Abenteurerin> wie Euch brauchen könnte. Stark. Robust. Willens, für ein kleines Handgeld zu arbeiten.\n\nEs ist, als wäret Ihr meinem Wunsch entsprungen. Das habe ich gut gemacht. Diese Ruinen haben die Aufmerksamkeit anderer erregt. Aber sie machen bei den Ausgrabungen bestimmt etwas falsch. Sie werden die Proben verderben!\n\nNehmt dies hier. Platziert es bei interessanten Artefakten in den Ruinen. Es ist so verzaubert, dass es alles Nötige erledigt.", sourceObjective = "Verwendet die verzauberten Werkzeuge in der Nähe von 5 Geröllhaufen.", completion = "Wir werden alles rechtzeitig einsammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[65892] = { id = 65892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zersplitterte Splitterflammen" }
quests[65893] = { id = 65893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reliktsuche", description = "Die Splitterflammen sind hier. Würdet Ihr irgendwelchen Splittern kostbare Artefakte anvertrauen?\n\nIch glaube kaum. Aber wir müssen herausfinden, was sie hier wollen, wenn wir weiterkommen möchten. Nehmt ihnen so viele wie möglich ab und zeigt sie mir dann.\n\nDieses Rätsel besteht aus mehr Teilen, als wir in der Erde finden werden.", sourceObjective = "Sammelt 60 Artefaktfragmente von Nelthazan.", progress = "Diese Ruinen sind schon kaputt genug.", completion = "Sie suchen immer noch etwas? Warum habt Ihr mir dann diesen Schrott mitgebracht?\n\nWir müssen es vor ihnen finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[65895] = { id = 65895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konkurrenz belebt das Geschäft", description = "Pah! Durch das Abschlachten von Arbeitern werden wir auch nicht schlauer.\n\nSucht ihre Anführer. Einer davon wird wissen, was wir benötigen.\n\nAch, und noch etwas, {name}. Belauscht sie dieses Mal, bevor Ihr sie umbringt. So erfahrt Ihr vielleicht etwas Nützliches.", sourceObjective = "Sammelt Informationen über die Splitterflammen.", progress = "Was habt Ihr erfahren?", completion = "So eine Krankheit ist mir schon einmal untergekommen. Ich hatte allerdings gehofft, das nicht noch einmal erleben zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65896] = { id = 65896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Wunden", description = "Dachtet Ihr wirklich, Ihr könntet Euch unbemerkt in diese Stadt stehlen? Nein, mir entgeht nichts!\n\nIch hatte schon einmal recht, was Eure Art betrifft, und ich will verdammt sein, wenn ich die Drachen meine Heimat erneut zerstören lasse.\n\nDies war einst ein Park voller Frieden und Gelächter. Doch dann kam Euer Ahne, Todesschwinge. Oh ja, ich weiß alles über ihn.\n\nSeht Euch doch das Vermächtnis der Zerstörung an, das er hinterlassen hat. Der Schmerz hallt bis heute in den Straßen wider.", sourceObjective = "Helft den Bewohnern von Sturmwind, die Wunden der Vergangenheit zu heilen.", completion = "Ihr habt mir heute das wunderbarste aller Geschenke gemacht und mir gezeigt, dass meine Stadt bereit ist, die Wunden der Vergangenheit zu heilen. Wir entscheiden selbst über unser Schicksal.\n\nGeht hin in Ehre, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[65898] = { id = 65898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protoprobleme", sourceObjective = "Beschafft den Locus und besiegt den Protodrachen, der ihn bewacht.", progress = "Schön, dass Ihr es in einem Stück da raus geschafft habt. Habt Ihr den Locus?", completion = "Ich danke Euch, {name}.\n\nIhr wart eine große Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[65899] = { id = 65899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Theramus", description = "{race}! Seid Ihr hier, um den wunderschönen Fliederstreifen zu besichtigen? Tut mir leid, dass er sich gerade in solch einem Zustand befindet. Ich schwöre, dass er normalerweise nicht so ungepflegt aussieht!\n\nTheramus, der Hüter des Gartens, wollte sich heute eigentlich mit uns treffen, damit wir die Probleme angehen können. In letzter Zeit ist er mit der Pflege etwas überfordert, also helfen Felina und ich aus. Aber wir können nicht alles erledigen.\n\nWürdet Ihr für uns nach ihm suchen? Vielleicht hat er es vergessen.", sourceObjective = "Durchsucht die nahe gelegenen Höhlen und findet Theramus.", completion = "Ihr habt ihn gefunden! Sieht aus, als wäre er heute wirklich zu nichts zu gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65900] = { id = 65900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtig gewürztes Steak", description = "Die Idee meiner Schwester ist bezaubernd, aber Theramus braucht einen echten Muntermacher.\n\nEine großzügige Portion Sauerblüte ist genau das Richtige. Wir können daraus eine Paste herstellen, die ich auf sein Lieblingsessen streichen kann: Schildkrötenfleisch!\n\nHelft Ihr mir, die Zutaten zu beschaffen?", sourceObjective = "Sammelt 2 Stücke wunderbar zartes Schildkrötenfleisch, 6 Reptilieneierschalen und 15 Sauerblüten.", progress = "Wisst ihr, warum die Sauerblüte unter den Bäumen an der Küste wächst?\n\nDie Baumwurzeln fangen eine Fülle von Nährstoffen aus den Wellen auf, die dann wiederum die Sauerblüte ernähren. Dadurch erhalten sie einen unglaublichen Nährwert.", completion = "Das Verhältnis von Fleisch zu Sauerblüte ist genau richtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[65901] = { id = 65901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rausschleichen", description = "Ich habe Hausarrest für unbestimmte Zeit! Weiß meine Ohn nicht, dass ich nächstes Frühjahr sechzehn werde? Ich sollte weggehen dürfen, wann immer ich will.\n\nIhr seht aus, als könntet Ihr mir helfen. Ich habe einen Fluchtplan: Indem ich diese Totems kanalisiere, kann ich die Luft konzentrieren und einen ordentlichen Wirbel erzeugen. Aber ich kann nicht herumlaufen und sie platzieren, ich stehe nämlich unter maximaler Windaufsicht. Sogar Togo wird mir nicht helfen.\n\nAber mit Eurer Hilfe... bitte! Ich verspreche Euch, ich werde Euch etwas Großartiges zeigen.", sourceObjective = "Platziert die Lufttotems in Quellen von Ohn'iri und informiert danach Radiya.", progress = "Wenn Ihr mich verpfeift, werde ich Euch mit dem windigsten Geist verfolgen... AUF EWIG! Tut es nicht!", completion = "Puh, danke! Freiheit!", sourceObjectiveStatus = "unverified-source-field" }
quests[65902] = { id = 65902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futter oder Flausch", description = "Sieh sich einer dieses saftige und köstlich gewürzte Schildkrötenfleisch an! Das ist natürlich nur eine rein objektive Betrachtung. Ich bin Vegetarierin.\n\nNa los! Er hat den vermutlich den ganzen Tag über noch kein Fleisch gegessen.", sourceObjective = "Bringt das gewürzte Schildkrötenfleisch und die Wiesenspringer zu Theramus.", progress = "Los, bevor das Fleisch alt wird!", completion = "Oh je. Wir haben seinen Wutausbruch gehört. Geht es Euch gut?", sourceObjectiveStatus = "unverified-source-field" }
quests[65903] = { id = 65903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flausch ist unschlagbar", description = "Armer Theramus. Ich habe eine Idee, wie man ihn wieder aufmuntern kann!\n\nNehmt dieses Netz und fangt ein paar der einheimischen Springer. Sie sind zwar friedlich, aber schnell. Sie haben sich an der Küste gut eingelebt.\n\nWir werden sie zu Theramus bringen. Er wird buchstäblich von flauschigen Freuden überschwemmt werden!", sourceObjective = "Fangt 12 Wiesenspringer.", progress = "Sie sind unglaublich weich! Ich könnte den ganzen Tag damit verbringen, sie zu streicheln.", completion = "So! Viele! Hopfer! Streicheln wir sie alle!", sourceObjectiveStatus = "unverified-source-field" }
quests[65904] = { id = 65904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug ist genug", description = "Griesgrämig oder nicht, Theramus hat eine Aufgabe zu erledigen. Solange er sich drinnen versteckt, kann er die Folgen seiner Abwesenheit nicht abschätzen.\n\nLasst uns zusammen gehen. Wir werden ihm die Beweise präsentieren.", sourceObjective = "Bringt die Beweise für die Schäden im Fliederstreifen zu Theramus.", progress = "Das würde jeden überzeugen, dass der Hain sofort Hilfe braucht!", completion = "Ich glaube, es hat funktioniert! Er hat die Höhle verlassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65905] = { id = 65905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als Unkraut", description = "Vielleicht sollten wir Theramus etwas Freiraum lassen.\n\nAber wir dürfen deshalb nicht untätig sein. Der Hain zerstört sich mit zunehmender Geschwindigkeit selbst. Bitte helft uns!", sourceObjective = "Beseitigt Überwucherungen und Monster im Fliederstreifen.", completion = "Habt Dank, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[65906] = { id = 65906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine aufgebrachte Initiandin", description = "Ich habe einen interessanten Brief von den Quellen von Ohn'iri erhalten.\n\nWas den Inhalt des Briefes angeht, so beschreibt er, ich zitiere, furchtbare Gefangenschaft, kontrollwütige Mentoren und extreme Langeweile. Er ist formell unterzeichnet, Initiandin Radiya. Schaut, da ist auch eine Zeichnung von einem Adler... er tritt eine Zentaurin namens Meluun von einer Klippe.\n\nNun. Ich vermute, es handelt sich hier um einen Hilferuf, falls Ihr es Euch selbst ansehen möchtet. Um ehrlich zu sein, ich glaube, Radiya ist in Ordnung. Sie schickt mir häufig solche Briefe.", sourceObjective = "Sprecht mit Initiandin Radiya bei den Quellen von Ohn'iri auf den Ebenen von Ohn'ahra.", completion = "Wer seid Ihr? Ordven schickt Euch? Er liest wirklich meine Briefe?!\n\n<Radiya schnaubt überrascht und erfreut.> Danke Ohn'ahra!", sourceObjectiveStatus = "unverified-source-field" }
quests[65907] = { id = 65907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblingsobst", description = "Die Mystikerausbildung ist so langweilig. Die Hälfte der Zeit beobachte ich Wasser dabei, wie es nass ist. Meine Brüder sind schon draußen in der Wildnis unterwegs, verändern die Welt und jagen Drachen und Primalisten.\n\nEgal. Ich habe versprochen, Euch etwas Großartiges zu zeigen! Wusstet Ihr, dass Schlammstampfer Strauchfrucht lieben? Sie wächst in der Nähe bei den Geysiren. Sammelt ein paar davon, dann können wir sie gemeinsam füttern.", sourceObjective = "Sammelt wilde Strauchfrüchte aus den Geysiren von Ohn'iri und füttert damit 6 faulenzende Schlammstampfer.", progress = "Strauchfrucht habe ich wirklich gerne gemocht, bis ich eines Tages zu viel davon gegessen habe.\n\nMein ganzer Körper hat gezittert wie bei einer starken Erkältung, und mein Atem hat danach noch tagelang nach Minze gerochen.", completion = "Anscheinend mögen sie Euch! Oder einfach nur die Früchte. Das ist auch in Ordnung. <Radiya zwinkert Euch zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65911] = { id = 65911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azurblaue Ausrichtung", description = "Die Bande dieser Gemeinschaft... Freunde, Familie... die Vertrautheit, die sie miteinander teilen.\n\nIch... hatte so etwas nie. Der blaue Drachenschwarm hatte so etwas nie. Und vielleicht liegt es daran, dass wir nie die Gelegenheit dazu hatten.\n\nJetzt haben wir sie. Ich muss meinesgleichen versammeln.\n\nSucht mich in den Azurarchiven auf. Es gibt viel zu tun.", sourceObjective = "Kehrt zu Kalecgos in den Azurarchiven zurück.", completion = "Ich hätte niemals gedacht, so viel von den Tuskarr zu lernen. Ich denke, wenn möglich werde ich sie besuchen, um die Bande der Freundschaft aufrechtzuerhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65913] = { id = 65913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles güter, Hüter?", description = "Den Titanen sei Dank! {class}, wir brauchen Eure Hilfe!\n\nGerade eben erst wurden wir von Primalisten angegriffen. Meine Schwestern und ich konnten sie abwehren, aber nur unter schweren Verlusten...\n\nWir haben Zeit zum Trauern, sobald meine Hüterin in Sicherheit ist! Eine Gruppe Primalisten hat sich während der Kämpfe abgesetzt... Ich schwöre, wenn sie unserer Hüterin Leid zufügen...\n\nIhr müsst ihr helfen, bevor es zu spät ist!", sourceObjective = "Rettet Hüterin Mara vor den Primalisten im Tyrholdreservoir.", completion = "Habt Dank, {race}. Ohne Eure Hilfe wäre ich gewiss nicht mehr am Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[65914] = { id = 65914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mammuts im Mittelpunkt", description = "Unser Stamm hat sich damit gerühmt, die On'tuq-Mammutherde seit Generationen heranzuziehen. Jetzt sind sie... verloren.\n\nNach diesem Massaker werden ihre Seelen sicher in Rage gefangen sein. Wir müssen ihnen die letzte Ehre erweisen, indem wir ihre Überreste sinnvoll verwerten.\n\nEs sind zu viele, wir können sie nicht alleine einsammeln. Bitte sammelt so viele Materialien von den Jungen und den Matriarchinnen ein, wie Ihr könnt, und trefft mich im Kauriqweiler.", sourceObjective = "Sammelt On'tuq-Hautfetzen und On'tuq-Stoßzähne von gefallenen Mammuts der On'tuq in der Nähe des Kauriqweilers.", progress = "Meine Kinder hatten sich bereits Kälber ausgesucht, die sie zu ihren Begleitern heranzüchten wollten. Wie soll ich ihnen das erklären?", completion = "Mit diesen Überresten können wir sicher etwas ganz Besonderes machen... etwas, das den Seelen dieser Mammuts Frieden bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65916] = { id = 65916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir verhandeln nicht mit Primalisten", description = "Die Primalisten glaubten, sie könnten die Macht von Tyr übertreffen. Da lagen sie falsch.\n\nMeine Refti konnten sie in einer Höhle nicht weit von hier aufspüren. Wie ich dachte, befinden sie sich im Besitz der verschwundenen Schlüsselsteine.\n\nChampion, wenn wir dem Reservoir zu alter Pracht verhelfen wollen, müssen wir diese Steine zurückerlangen.\n\nAußerdem muss ihr Anführer sterben, damit sie keinen erneuten Angriff starten können.", sourceObjective = "Tötet Primalistenanführer Ko'jo und erlangt die fehlenden Schlüsselsteine im Tyrholdreservoir zurück.", progress = "Sicher wird Zuttiki nicht mehr so... kläglich aussehen, wenn wir die Schlüsselsteine wiederhaben.", completion = "Habt Dank, {name}. Nun obliegt es uns noch, die Schutze zu reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65918] = { id = 65918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbeugende Maßnahme", sourceObjective = "Tötet 8 entfesselte Elementare im Tyrholdreservoir.", completion = "Habt Dank, {name}. Das sollte sie fürs Erste in Schach halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65920] = { id = 65920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für den Schutz!", sourceObjective = "Nutzt die fehlenden Schlüsselsteine, um die Reservoirschutze zu reparieren, und aktiviert dann die Konsole.", progress = "Kehrt hierher zurück, um die Schutzkonsole zu aktiveren, sobald alle drei Schutze repariert sind.", completion = "Hervorragende Arbeit, {name}. Die Schutze sind wiederhergestellt und das Tyrholdreservoir ist erneut geschützt. Danke für alles, was Ihr getan habt. Thaldraszus steht tief in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[65921] = { id = 65921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung der Refti", sourceObjective = "Tötet Primalisten und rettet Refti im Tyrholdreservoir.", completion = "Es wird mich bis in alle Ewigkeit schmerzen, wen wir alles verloren haben, doch ich bin dankbar für alle, die wir retten konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65925] = { id = 65925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlächter schlachten", description = "Diese Wyrms gehören nicht hierher. Ich weiß nicht, was sie aus ihren unterirdischen Höhlen getrieben hat, aber jetzt können wir ihnen nicht mehr helfen.\n\nWir dürfen nicht zulassen, dass sie die einheimische Fauna zerstören.\n\nTötet die Wyrms, {name}. Behaltet ihre Einzelteile, wenn nötig, und sucht mich im Weiler auf, sobald Ihr fertig seid.", sourceObjective = "Tötet Eiskriecher und Eisbohrer in der Nähe des Kauriqweilers.", completion = "Es ist eine Schande, ein Leben auszulöschen... auch wenn es nur Ärger macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[65926] = { id = 65926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wasserfälle bezwingen", description = "Kennt Ihr die Geschichte der Leuchtfischerin? Sie hat ein Boot gebaut, stark genug, um Wasserfälle hinunterzufahren!\n\nDie Älteste Nava liebt es, diese Geschichte zu erzählen.\n\nIch denke, den ehrwürdigen Geistern der On'tuq-Mammuts würde es große Ehre erweisen, wenn wir das Material aus ihren Körpern nutzen würden, um erneut ein solches Boot anzufertigen.\n\nMein Bruder ist dagegen, aber wenn es uns gelingt, könnten wir dabei helfen, Fische zu unseren Schwesterstämmen zu bringen, die es gerade sehr schwer haben.\n\nIhr habt Eure Fähigkeiten und Eure Leidenschaft bereits bewiesen! Gemeinsam können wir sicherlich etwas Großes erschaffen.", sourceObjective = "Helft Ruriq dabei, die Fallschreiter zu bauen.", progress = "Das wird das beste Boot, das unser Stamm seit Generationen gesehen hat!", completion = "Ruriq ist so stur wie eh und je.", sourceObjectiveStatus = "unverified-source-field" }
quests[65928] = { id = 65928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unberechenbare Winde", description = "Pah! Zusammenarbeiten will sie?\n\nAber... wenn die Leuchtfischerin denkt, dass wir damit den anderen Stämmen vielleicht helfen können... müssen wir es versuchen.\n\nDamit der Windgeist Kraunot von uns Notiz nimmt, müssen wir uns zuerst um sein Element kümmern. Die Windelementare in der Nähe sind aufgewühlt, seit das Land erwacht ist.\n\nWährend ich das Boot inspiziere, das Ihr zwei gebaut habt, könnt Ihr sie bekämpfen und mir ihre ruhelosen Partikel bringen. Das sollte die Ruhe in der Gegend wiederherstellen.", sourceObjective = "Sammelt 10 ruhelose Windpartikel von den ruhelosen Winden in der Nähe des Kauriqweilers.", progress = "Keine Sorge, dass diese Windelementare hier sind, bedeutet nur, dass sie aufgewühlt sind. Wenn wir sie vernichten, können wir die Winde hier beruhigen.", completion = "Ich kümmere mich um diese Partikel, damit sie sich harmlos zerstreuen. Kraunot wird zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[65929] = { id = 65929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisbrecher", description = "Ich wusste, dass die Ahnen ihren Segen geben würden!\n\nWobei ich nicht viel über Geister weiß, Kauj ist der Schamane. Aber wir müssen die großen Geister der Luft und des Wassers beschwichtigen, bevor sie sich uns zeigen.\n\nJeder kann sehen, wie die Wasserelementare oben auf dem Berg langsam einfrieren. Das ist kein natürlicher Frost. In letzter Zeit strömt wesentlich mehr Kälte vom Berg herunter als sonst. Wenn niemand etwas dagegen unternimmt, könnte unser gesamter Fluss vereisen.\n\nBefreit sie aus ihren frostigen Gefängnissen!", sourceObjective = "Befreit gefrierendes Wasser aus dem Eis in der Nähe des Kauriqweilers.", completion = "Exzellent. Otu'rorq, der hiesige Flussgeist, wird erfreut sein, zu hören, dass sein Fluss vorerst weiter fließen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[65930] = { id = 65930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ringen von Wind und Wasser", description = "Jetzt sollten wir uns den Geistern entgegenstellen können.\n\nHat Ruriq das nicht erwähnt? Die Traditionen unseres Stamms schreiben es vor, dass wir uns den Geistern im Kampf stellen müssen, bevor wir ihren Segen erbitten. Wie stark er ausfällt, hängt davon ab, wie sehr man sie beeindruckt hat.\n\nVielleicht hat die Leuchtfischerin deshalb darauf bestanden, dass wir alle zusammenarbeiten.\n\nKümmert Ihr Euch um Kraunot, den Geist der Luft, dann übernehmen Ruriq und ich Otu'rorq, den Geist des Wassers.\n\nSie leben in der Höhle hinter dem Wasserfall gleich in der Nähe. Wir sehen uns dort, <Abenteurer/Abenteurerin>.", sourceObjective = "Stellt Euch Kraunot, dem Geist der Luft, in der Nähe des Kauriqweilers.", progress = "Wir müssen diese Geister beeindrucken, wenn wir Ruriqs Vision in die Realität umsetzen wollen.", completion = "Da Kauj so viel älter ist als ich, war er stets... fast mehr ein Vater denn ein Bruder für mich.\n\nIch dachte, wenn ich älter werde und meine eigene Familie gründe, lässt das Gefühl, ihn zu brauchen, etwas nach.\n\nIch lag falsch. Selbst vor dem Tod meiner Frau lag ich schon falsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[65935] = { id = 65935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromie einholen", description = "Ihr habt uns geholfen, die Kontrolle über die Sande wiederzuerlangen, doch oben auf den Tempelplattformen spüre ich noch etwas Größeres. Lasst uns in die Lüfte steigen und uns dort oben mit Botschafterin Chronormu treffen.\n\nWie immer ist Eile geboten.", sourceObjective = "Trefft Chromie auf den Plattformen des temporalen Konflux.", completion = "Es ist an der Zeit! Eternus mag in dieser Blase wie eingefroren aussehen, aber sie kämpft mit all ihrer Macht, um sich zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[65937] = { id = 65937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Beweis der Nachlässigkeit", description = "Wir dürfen nicht aufgeben. Er muss begreifen, was hier draußen geschieht! Wenn er die Höhle nicht verlassen will, müssen wir es ihm eben direkt zeigen.\n\nDazu könnte sicher alles Mögliche dienen. Es läuft so vieles schief, von der verderbten Flora bis hin zur leidenden Fauna!", sourceObjective = "Findet Beweise für die Schäden im Fliederstreifen und zeigt sie Theramus.", progress = "Es ist furchtbar, den Hain und Theramus in solch einem Zustand zu sehen.", completion = "Ihr seid zurückgekehrt!", sourceObjectiveStatus = "unverified-source-field" }
quests[65938] = { id = 65938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das einstige und zukünftige Team", description = "Alles klar! Zerstören wir die Stasisblase um die Tempeltüren herum und befreien wir unsere Wächter! Seid Ihr bereit für ein gewaltiges Tauziehen gegen die Zeit selbst?\n\nZieht an der Blase an der Tür wie zuvor an den Kristallen. Aber nehmt Euch in Acht: Die freigesetzte Zeitenergie wird sich gewiss sammeln und Euch angreifen. Ich weiß nicht genau, was Euch erwartet, aber immerhin werden die befreiten Wächter an Eurer Seite kämpfen, was auch geschieht.\n\nViel Glück, {name}!", sourceObjective = "Nutzt Euren Zeitwandererstab, um die Stasisblase an der Tempeltür zum Platzen zu bringen.", progress = "Wir hätten das wirklich vorhersehen sollen, als wir damals unser Sicherheitssystem gebaut haben...", completion = "Das ist der zweitgrößte Zeitelementar, den ich je gesehen habe! Ich hätte heute meine S.E.L.F.I.E.-Kamera mitnehmen sollen.\n\nMacht nichts. Ich werde diesen Moment einfach an meinem nächsten freien Tag noch einmal besuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65939] = { id = 65939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mut der Überzeugung", description = "Eine heftige Schlacht steht uns bevor, aber unser Mut und unsere Entschlossenheit werden uns ihre zahlenmäßige Überlegenheit überwinden lassen.\n\nIch verlasse mich darauf, dass Ihr unsere Truppen mit Euren hervorragenden Fähigkeiten zum Sieg führen werdet.\n\nWir werden den Angriff beginnen, wenn Ihr bereit seid.", sourceObjective = "Erlangt die Kontrolle über die Obsidianzitadelle.", progress = "Wir haben die Zitadelle erobert.", completion = "Exzellent, {name}. Die Streitkräfte der Djaradin sind auf der Flucht! Wir kontrollieren den oberen Hof der Zitadelle. Aber die Gewölbe unten werden vermutlich nicht so schnell zu sichern sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[65940] = { id = 65940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zerstörten Wegen", description = "Ich hoffe, dass Ihr nichts gegen nasse Füße habt. Der nächste Teil unserer Reise führt uns über zwei Flüsse.\n\nOhn Seshteng möchte Euch eine Geschichte über unsere gesegnete Wächterin Ohn'ahra erzählen. Ich lasse Euch mit Freuden in ihrer Obhut.", sourceObjective = "Reist zusammen mit der Shikaarkarawane zum Flussübergang.", completion = "Ich spüre etwas im Wind.", sourceObjectiveStatus = "unverified-source-field" }
quests[65943] = { id = 65943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uroffensive", description = "Khadgar und ich tun unser Bestes, um die Primalisten im Himmel abzuwehren, aber wir kommen nicht näher an den Turm heran.\n\nIhr müsst ihre Truppen am Boden dezimieren, damit wir uns Raszageth nähern und sie aufhalten können, bevor es zu spät ist.\n\nKämpft Euch zu den Primalisten voraus durch. Wenn ich meine Konzentration aufrechterhalten kann, wird dort ein weiteres Abbild auf Euch warten.", sourceObjective = "Besiegt 15 Primalisten in Vakthros.", completion = "Gute Arbeit, ein paar ihrer Streitkräfte steigen herab.", sourceObjectiveStatus = "unverified-source-field" }
quests[65944] = { id = 65944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lavaeruption", description = "Die Primalisten haben den Berg entzweigerissen, um ihre Streitkräfte nach Vakthros hineinströmen zu lassen!\n\nIch habe einige Lavakugeln im vorderen Korridor erspäht, die sie nutzen, um ihr elementares Chaos weiter zu verbreiten.\n\nVernichtet sie, um ihr Vorrücken zu verlangsamen. Ich werde von hier oben aus tun, was ich kann, um Kalecgos zu helfen.", sourceObjective = "Zerstört 3 Lavakugeln.", completion = "Das sollte sie etwas aufhalten. Anscheinend bin ich etwas eingerostet seit dem Kampf gegen die Brennende Legion...", sourceObjectiveStatus = "unverified-source-field" }
quests[65947] = { id = 65947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitfixierte Zeitwanderer", description = "Ich bin so froh, dass Ihr hier seid! Ihr müsst die Lage hier auf den Plattformen für mich stabilisieren, während Dante und Zera mir helfen, unsere ewige Drachenfreundin festzuhalten.\n\nDie Sicherheitsvorkehrungen des Tempels haben Eternus in eine Stasisblase gesperrt, als sie versuchte, die Kontrolle über unseren Schwurstein zu erlangen. Unglücklicherweise wurden einige der anderen Zeitwanderer ebenfalls von diesen Sicherheitsvorkehrungen getroffen.\n\nMit Eurem Zeitwandererstab solltet Ihr sie problemlos befreien können... Kümmert Euch nur um die wütenden Zeitlinge, die dabei auftauchen!", sourceObjective = "Befreit 8 Zeitwanderer aus Zeitblasen.", completion = "Es hat funktioniert? Ich bin nicht überrascht... jedenfalls nicht allzu sehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[65948] = { id = 65948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Risse in der Zeit", description = "Als der Tempel verschlossen wurde, sind die Wächter ebenfalls eingeschlossen worden. Wenn wir sie rausholen wollen, müssen wir die Stasisblase platzen lassen! Dafür braucht Ihr leider einen vollständig ermächtigten Zeitwandererstab...\n\nOh, ich weiß! Ihr könnt Energie aus den Kristallen hier auf der Plattform ziehen. Das sollte Eurem Stab genug Wumms verleihen.\n\nDie Kristalle haben selbst Stasisfelder, also reißt sie einfach heraus und absorbiert ihre Energie mit Eurem Stab.\n\nUnd keine Sorge, falls sie zerbrechen: Die Kraft wohnt ihnen weiter inne, selbst wenn sie in Stücken sind!", sourceObjective = "Nutzt die östlichen und westlichen Kristalle, um Euren Zeitwandererstab weiter zu verstärken.", completion = "Ausgezeichnete Arbeit!\n\nDamit solltet Ihr mehr als genug Zeitenergie haben, um die Wächter zu befreien!", sourceObjectiveStatus = "unverified-source-field" }
quests[65949] = { id = 65949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsame Eisen", description = "Wenn wir uns Ohn'ahra im Wind anschließen, hinterlassen wir diese Medaillons.\n\nObwohl ich geholfen habe, dieses Medaillon herzustellen, bin ich nicht sein rechtmäßiger Besitzer.\n\nEs sollte zu Roscha zurückgebracht werden. Es ist die letzte Erinnerung an ihre Verlobte.\n\nBringt es zu ihr, damit sie trauern und ihren Frieden finden kann.", sourceObjective = "Bringt das Medaillon zu Hufschmiedin Roscha zurück.\n\nBereitgestellter Gegenstand:", completion = "Ist das... ah. Ja. Dann ist meine Geliebte im Himmel und galoppiert mit Ohn'ahra. Ich werde mich ihr anschließen... zu gegebener Zeit.\n\nHabt Dank, {name}.\n\nIch werde nicht vergessen, was Ihr für den Klan Shikaar getan habt. Und für mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[65950] = { id = 65950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Gorlocs", description = "Ist Hufschmiedin Roscha zur Karawane eingeladen? Nein! Aber wer muss Hufeisen für die Karawane anfertigen? Hufschmiedin Roscha. Und wen bestehlen die Schlickflossen? Natürlich Hufschmiedin Roscha. Pah.\n\nIch würde ja Khasar losschicken, aber wer weiß, wo der sich gerade wieder rumtreibt?\n\nFindet meine Vorräte. Zeigt diesen Kreaturen, dass man nicht von Hufschmiedin Roscha stiehlt.\n\nLos!", sourceObjective = "Bringt die gestohlenen Vorräte aus dem Schlickflossendorf zurück.", progress = "Hier sind zu viele Gorlocs. Wir sind hier nicht sicher.", completion = "Roscha schickt Euch? Sie muss rasend vor Wut sein.\n\nSie hat schon so vieles durchgemacht. Ich könnte niemals zurückkehren, ohne alles zurückzubringen, was verloren ging.", sourceObjectiveStatus = "unverified-source-field" }
quests[65951] = { id = 65951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sohlenlieferant", sourceObjective = "Sucht den Wald nach Khasar ab.", completion = "Habt Dank, {name}. Gehen wir an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[65952] = { id = 65952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendärer Häuptling", description = "Die Gorlocs dieses Sumpfes waren einst simple Kreaturen. Lästig, sicher, aber niemals Plünderer, Diebe oder Hundefresser.\n\nEs ist ihr Häuptling Grrlgllmesch, der sie dazu gebracht hat, sich von ihrer wahren Natur abzuwenden.\n\nSetzt ihm ein Ende, damit die Gorlocs keine Bedrohung mehr für uns darstellen.", sourceObjective = "Tötet Häuptling Grrlgllmesch.", progress = "Häuptling Grrlgllmesch ist eine Geißel dieser Gegend.", completion = "Nachdem ihr Häuptling erschlagen ist, werden die Gorlocs uns nicht mehr behelligen.\n\nErstaunlich, wie stark sie unter Häuptling Grrlgllmesch geworden sind.\n\nIch habe nie gesehen, dass solch primitive Kreaturen sich gegen eine mächtige Zivilisation wie die unsere erheben. Sind wir gar nicht so unterschiedlich? So viel weiter entwickelt? Vermutlich nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[65953] = { id = 65953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ora-Keulen", description = "Unter all dem Wahnsinn, der sich in diesem Gorlocdorf abspielt, habe ich nichts Bedenklicheres entdeckt als die Gorlocschamanen.\n\nSie sind besonders bösartig und spielen leichtsinnig mit Sturmmagie, ohne die Konsequenzen zu bedenken.\n\nDas muss ein Ende haben. Tötet sie und bringt mir ihre Totems. Unsere Mystiker werden an ihnen sehr interessiert sein.", sourceObjective = "Sammelt 4 Totems von Gorlocschamanen.", progress = "Die Gorlocschamanen sind zu weit gegangen.", completion = "<Khasar sieht die Totems missbilligend an.>\n\nDiese Totems dienen der Sturmmagie. Sturmmagie ist ein Sakrileg gegen das Geschenk des Windes, das Ohn'ahra selbst uns gab.\n\nIch werde sie zu den Mystikern bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65954] = { id = 65954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hunde loslassen", description = "Ich habe das Heulen und Bellen der Bakar gehört, die aus dem Lager verschwunden sind.\n\nUnsere geliebten Hunde werden in Käfigen gefangen gehalten und warten darauf, von diesen... Dingern in Stücke gerissen zu werden.\n\nWir sind unseren Begleitern gegenüber verpflichtet zu helfen. Befreit sie und werdet <Zeuge/Zeugin> der wahren Macht der Bakar der Shikaar!", sourceObjective = "Befreit die Bakar der Shikaar.", completion = "Herrliche Tiere, nicht wahr?\n\nJeder Bakar hat einen besonderen Platz im Klan Shikaar. Sie sind unsere Jagdgefährten, unsere Wachen und unsere liebsten Freunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[65955] = { id = 65955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Freund eines Zentauren", sourceObjective = "Befreit Khasar und trefft ihn in der Höhle.", completion = "Habt Dank, {name}. Hier sind wir sicher und können frei sprechen.\n\nIch werde Baba vor jedem Gorloc beschützen, der sich hierher verirrt, während er schläft.", sourceObjectiveStatus = "unverified-source-field" }
quests[65956] = { id = 65956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krallenschlag", description = "Mit Eurer Hilfe werden meine Schwarzkrallenassassinen die Djaradin beseitigen, die die äußeren Gebiete verteidigen. Markiert potenzielle Ziele mit kleinen Betäubungsbomben und meine Assassinen erledigen den Rest.\n\nSputet Euch und eliminiert alles, das unser Vordringen behindern könnte.", sourceObjective = "Stört die Djaradinverteidigung.", progress = "Habt Ihr ihre Verteidigung ausgeschaltet?", completion = "Unser Vorstoß drängt sie zurück! Jetzt müssen wir nur noch die Tore durchbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65957] = { id = 65957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit für Helden", description = "Unseren Beobachtungen nach zu urteilen, basiert die Gesellschaft der Djaradin auf Stärke. Die Stärksten unter ihnen dienen den anderen als Vorbild und motivieren sie zum Kämpfen.\n\nUnter den Streitkräften unter uns befinden sich einige Vertreter der mächtigsten Djaradin... Eure Ziele.\n\nIhr, {name}, werdet sie persönlich ausschalten. Das sollte ihrer Moral einen entscheidenden Dämpfer verpassen.", sourceObjective = "Tötet Modak Flammenspeier, Durchbohrerin Gigra und Olphis den Geschmolzenen.", progress = "Habt Ihr Eure Ziele ausgeschaltet?", completion = "Ihr seid der wahre Held des Tages, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[65958] = { id = 65958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgewalt", description = "Ich befürchte, es wird schwerer für mich, die Abbilder aufrechtzuerhalten. Die Primalisten konzentrieren sich zunehmend darauf, mich aus dem Himmel zu holen.\n\nAber keine Sorge... Ich habe einen Plan.\n\nIhr müsst die Kugel, die Ihr an Euch genommen habt, nutzen, um Elementarmagie getöteter Primalisten einzusammeln.\n\nDiese elementare Energie brauchen wir, um die Aufmerksamkeit ihrer Streitkräfte von mir abzulenken.", sourceObjective = "Nutzt den Elementarfokus, um Elementarenergie aus getöteten Primalisten und Elementaren zu extrahieren.", progress = "Wir müssen schnell handeln.", completion = "Diese Kugel ist erfüllt von Macht! Sie ist perfekt für das, was jetzt kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65962] = { id = 65962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der nie endende Countdown", description = "Ich hätte nie gedacht, dass ich unseren Tempel einmal retten würde, indem ich jene Sicherheitsmechanismen zerstöre, die ihn schützen sollen. Aber sei's drum!\n\nNachdem wir die Zeitelementare nun vernichtet haben, unsere Zeitwanderer befreit sind und unsere Wächter bereitstehen, wird es endlich Zeit, die letzte Stasisblase zu zerstören und uns um Eternus zu kümmern.\n\nLasst mich wissen, wenn Ihr bereit seid. Ich weiß, dass mit Euch an meiner Seite nichts schiefgehen kann.", sourceObjective = "Sprecht mit Chromie, wenn Ihr bereit seid.", completion = "Eternus und Chromie sind durch Raum und Zeit gefallen. Wir müssen sie zurückbringen, koste es, was es wolle!", sourceObjectiveStatus = "unverified-source-field" }
quests[65977] = { id = 65977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erholung der Kirin Tor", description = "Als die Primalisten unsere Expedition angegriffen haben, habe ich befürchtet, dass wir etliche Magier verloren hätten.\n\nAber es scheint, als hätten die Primalisten sie entführt und würden sie in diesem Moment foltern!\n\nBitte, Ihr müsst die überlebenden Magier retten. Sie mögen uns in diesem Kampf nicht unterstützen können, aber deshalb dürfen wir sie nicht im Stich lassen!", sourceObjective = "Rettet 6 sterbende Magier.", completion = "Ihr habt meinen Dank. Wir können in diesem Kampf niemandem im Stich lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65989] = { id = 65989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Djaradin auf dem Vormarsch", description = "Wir verfügen vielleicht nicht über die Streitkräfte, unseren Außenposten zurückzuerobern, aber wir müssen uns auch nicht kampflos ergeben.\n\nZeigt ihnen, dass wir immer noch Biss haben.", sourceObjective = "Tötet 6 Djaradin im Drachenherzaußenposten.", completion = "Großartig.", sourceObjectiveStatus = "unverified-source-field" }
quests[65990] = { id = 65990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welpenerlösung", description = "Sie fielen über uns her, bevor wir überhaupt reagieren konnten. Meine Wachen hielten so lange dagegen, wie sie nur konnten, während wir die Kleinen und Hilflosen in Sicherheit brachten. Ich befürchte aber, dass im Außenposten noch mehr von ihnen sind.\n\nÜberquert diese Brücke und sucht nach Überlebenden.", sourceObjective = "Rettet 4 wimmernde Welplinge aus dem Drachenherzaußenposten.", progress = "Wir werden die Stadt zurückerobern, sobald wir die nötigen Streitkräfte aufbringen können... aber fürs Erste müssen wir unsere eigenen Leute beschützen.", completion = "Wir können noch nicht rasten, aber jetzt, da wir sie gerettet haben, kann ich etwas freier durchatmen. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[65991] = { id = 65991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für eine Abrechnung", description = "Kadettin Sendrax hat mich über die Pläne von Majordomus Selistra informiert. Der Lebensbinderin sei Dank für diese Hilfe. Das Einschreiten gibt uns genug Zeit, unsere Verwundeten zur Behandlung zurück zu den Lebensbecken zu bringen.\n\nIch wünschte, ich könnte Selistra Verstärkung senden, doch ich brauche meine Wachen in der Nähe der Verwundeten. Begebt Euch zur feindlichen Festung und trefft sie dort.\n\nIch wünschte, es gäbe einen anderen Weg, die Djaradin unter Kontrolle zu bekommen. Aber es geht nicht anders...\n\nIhr müsst tun, was Ihr tun müsst.", sourceObjective = "Trefft Furorion und Majordomus Selistra bei der Schuppenknackerfeste.", progress = "An Selistras Seite zu fliegen, ist aufregend! Sie ist ganz ruhig, aber doch erstaunlich fähig.", completion = "Es tut gut, während dieser schrecklichen Zeit gute Nachrichten vom Drachenherzaußenposten zu hören. Die Flüchtlinge werden bei den Lebensbecken sicher sein.\n\nSelbst die Djaradin wagen es nicht, ihre Waffen gegen die Macht von Königin Alexstrasza zu erheben.", sourceObjectiveStatus = "unverified-source-field" }
quests[65992] = { id = 65992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzkralleninformationen", description = "Während Selistra und ich ihre Blicke nach oben lenken konnten, sind Schatten durch ihre Verteidigung geschlüpft.\n\nMeine Agenten, die Schwarzkrallen, halten in ihrer Festung Augen und Ohren offen. Trefft sie und lasst sie wissen, dass Ihr auf unserer Seite steht. Sie werden Euch wertvolle Informationen über unsere Feinde übermitteln.", sourceObjective = "Sprecht mit Furorions Spionen, die sich in der Schuppenknackerfeste versteckt halten.", progress = "Ich habe ihnen mein Leben anvertraut. Ihr könnt ihnen vertrauen.", completion = "Das ist gelinde gesagt beunruhigend. Ein weiterer Grund, sie zu bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65993] = { id = 65993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmungskiller", description = "Ah, ja.\n\nKurz nach meiner Ankunft habe ich gesehen, wie die Anführerin dieser Riesen von ihrem Raubzug zurückkehrte. Irgendwo im Lager feiert sie ihren Sieg.\n\nEs wäre eine Schande, wenn jemand ihre Feierlichkeiten stören würde, meint Ihr nicht auch?", sourceObjective = "Tötet Fleischwölfin Sotok in der Schuppenknackerfeste.", completion = "Die Djaradin scheinen einen unerschöpflichen Vorrat an Leichen zu haben, um sie uns vor die Füße zu werfen... aber vielleicht gebietet dieser Schlag ihnen Einhalt. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[65994] = { id = 65994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Djaradingerechtigkeit" }
quests[65995] = { id = 65995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Obsidianzitadelle", description = "<Auf den ersten Blick scheint es sich dabei um interne Kommunikation zwischen den Djaradinlagern zu handeln.\n\nDie Worte \"Obsidianzitadelle\" springen Euch ins Auge.\n\nMöglicherweise wäre Furorion hieran interessiert.>", sourceObjective = "Bringt die Pläne der Qalashi zu Furorion.\n\nBereitgestellter Gegenstand:", completion = "Welch ein Genuss! Ich sehe zu gern in den Geist meiner Feinde. Lässt mich schnell und zielsicher zuschlagen.\n\nMal sehen...\n\nDie Obsidianzitadelle?\n\nNein.\n\nNein!", sourceObjectiveStatus = "unverified-source-field" }
quests[65996] = { id = 65996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteranen zur Hilfe", description = "Kommandant Lethanak war wie gewohnt verständnisvoll. Wir werden die Hilfe unserer erfahrensten Wachen benötigen, um die Bedrohung abwenden zu können. Sie zu versammeln, war der perfekte Auftrag für eine junge Kadettin wie Sendrax, doch vielleicht könnte sie etwas Unterstützung brauchen.\n\nSendrax' Pfad führt sie nach Westen, der möglicherweise von dieser aufkommenden Bedrohung überwältigt wurde. Sie werden ebenfalls Unterstützung brauchen. Nehmt dieses Gebräu und unterstützt sie.", sourceObjective = "Helft den verletzten Wachen und findet Sendrax.", completion = "Sendrax kam vorbei und eilte gleich weiter. Ein echter Wirbelwind.\n\nIch mag sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[65997] = { id = 65997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sendrax auf der Spur", description = "Kadettin Sendrax kam hier vor nicht allzu langer Zeit vorbei.\n\nSie hatte den Befehl von Kommandant Lethanak für alle Drakoniden, sich bei den Lebensbecken zu sammeln. Unser gesamtes Verteidigungsregiment ist kurz darauf in diese Richtung aufgebrochen.\n\nUnsere Späher waren zu der Zeit jedoch noch auf Patrouille in den alten Ruinen, also ist sie ihnen hinterher, um auch ihnen die Befehle zu übermitteln.", sourceObjective = "Findet Sendrax in den Ruinen des Konservatoriums der Lebensbinderin.", progress = "Haltet Euch bedeckt, {name}.", completion = "Ich habe in den Archiven nichts davon gelesen, dass die Primalisten je Dracheneier gestohlen haben.\n\nDas ist nicht gut. Gar nicht gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[65998] = { id = 65998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukunft der Schwärme", sourceObjective = "Rettet die Rubindracheneier.", progress = "Solch Grausamkeit und Egoismus... Es ist mir unbegreiflich.", completion = "<Sendrax ist sichtlich erschüttert davon, was sie tun musste.>\n\nEin schneller Tod war die einzige Gnade, die ich den armen Welplingen noch erweisen konnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[65999] = { id = 65999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutrünstig", description = "Kommandant Lethanak warnte uns Rekruten, dass die Sturmfresserin Raszageth Berichten zufolge aus ihrem Gefängnis entkommen sein soll. Wie es scheint, sind ihre Untergebenen ihr gefolgt und bedrohen jetzt alles, was uns lieb und teuer ist.\n\nSie kommen schnell voran. Bei der letzten Patrouille wurden diese Ruinen noch als verlassen gemeldet.\n\nWir müssen die Primalisten hier aufhalten.\n\nFür die Lebensbinderin, und für alle Drachenschwärme!", sourceObjective = "Tötet 15 Eindringlinge der Primalisten.", progress = "Die Drachenschwärme werden die Primalisten bezwingen.", completion = "<Sendrax klopft eine kleine Flamme auf ihrer Rüstung aus.>\n\nWir haben getan, was wir konnten... Was getan werden musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[66000] = { id = 66000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bibliothek von Alexstrasza", description = "<Die Seiten dieses Buchs sind völlig verkohlt.\n\nDie Primalisten verbrennen offenbar gezielt die uralten Folianten und bedrohen damit die Geschichte der Drachenschwärme selbst. Es ist, als wollten die Primalisten die Drachenschwärme geradezu aus der Geschichte tilgen.\n\nRettet, was Ihr könnt.>", sourceObjective = "Rettet 4 Werke von kultureller Bedeutung.", progress = "Der Wind trägt den Geruch von verbranntem Pergament...", completion = "Unsere Geschichte wird überdauern.", sourceObjectiveStatus = "unverified-source-field" }
